contracts/BurnTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {CreditToken} from "./CreditToken.sol";
import {ProjectRegistry} from "./ProjectRegistry.sol";

/**
 * @title BurnTracker
 * @notice "Oracle interna" do modelo economico: contabiliza on-chain o burn de
 *         `CreditToken` (CREDIT) por `projectId` e por rodada, servindo como
 *         fonte unica da verdade para o futuro `RewardDistributor` (fase 4).
 *         Todo consumo de CREDIT dentro da plataforma passa por aqui via
 *         {burnAndRecord} — atomicamente a funcao queima o CREDIT do usuario
 *         (usando `BURNER_ROLE` do CreditToken) e grava o burn no par
 *         (round, projectId), mantendo tambem o total global da rodada e a
 *         contagem de projetos com burn (`projectsWithBurnCount`).
 * @dev Desenho — por que on-chain atomico (caminho "c") e nao event listener?
 *      Alternativas consideradas:
 *        (a) Apps queimam CREDIT direto e um indexer off-chain ouve o evento
 *            `Transfer(to=address(0))` para imputar burn a projeto.
 *            -> Rejeitada: depende de indexer confiavel, nao ha prova
 *               criptografica on-chain de "qual projeto consumiu este burn",
 *               e abre janela entre burn e record para race-conditions que
 *               o RewardDistributor nao consegue resolver deterministicamente.
 *        (b) Apps registram burn sem queimar e confiamos no app.
 *            -> Rejeitada: double-spend trivial (registrar burn sem queimar
 *               CREDIT inflacionaria reward sem deflacao).
 *        (c) Apps chamam `BurnTracker.burnAndRecord(projectId, from, amount)`
 *            atomicamente; o BurnTracker detem `BURNER_ROLE` no CreditToken e
 *            queima via `burnByRole` sem allowance. <-- Adotada.
 *      Como CreditToken.burnByRole NAO tem callback para o usuario `from`
 *      (apenas um `_burn` nativo ERC-20), o risco de reentrancia real e
 *      ZERO no nosso pipeline. Ainda assim aplicamos `nonReentrant` em
 *      {burnAndRecord} como defesa-em-profundidade: recorders sao terceiros
 *      (apps listados) e nao controlamos o bytecode deles. Um recorder
 *      malicioso nao consegue reentrar em `burnAndRecord` via `burnByRole`,
 *      mas se um dia adicionarmos hook / callback em outra via, o guard
 *      evita regressao silenciosa.
 *
 *      Invariantes atendidas nesta unidade:
 *       - I2 (burn no consumo): CREDIT e queimado via `_burn` nativo no
 *         CreditToken; `totalSupply` decrementa em exatamente `amount` a
 *         cada `burnAndRecord`. Teste integrado valida o decremento.
 *       - I3 (cap por rodada) — na dimensao CREDIT *queimado*, aplicamos um
 *         sanity cap por (round, projectId) via `maxBurnPerRoundPerProject`.
 *         NAO e o cap de mint (isso vive no futuro RewardDistributor); aqui
 *         evitamos wash-burn catastrofico: um projeto malicioso queimando
 *         10^30 CREDIT num unico tx para capturar share desproporcional
 *         dentro da rodada. Cap == 0 desliga o gating (opt-out explicito
 *         via governanca).
 *       - I4 (governanca via Timelock): {closeRound}, {setRoundDuration} e
 *         {setMaxBurnPerRoundPerProject} sao `onlyRole(GOVERNANCE_ROLE)`;
 *         `GOVERNANCE_ROLE` e concedida ao `TimelockController` em producao.
 *       - I7 (listagem via governanca): projetos so sao `Active` no Registry
 *         apos proposta aprovada no Governor + delay do Timelock;
 *         `burnAndRecord` le `Registry.isActive(projectId)` e reverte com
 *         `ProjectNotActive` caso contrario (Pending, Probation ou Removed).
 *         Decisao consciente: se um projeto vira Probation/Removed DEPOIS de
 *         ja ter queimado na rodada atual, o burn ja registrado nao e
 *         revertido — historia e historia e a matematica da rodada deve
 *         permanecer consistente. Apenas novos burns sao bloqueados.
 *
 *      Politica de close de rodada:
 *       - {closeRound} e `onlyRole(GOVERNANCE_ROLE)` — nunca permission-less.
 *         Motivacao: evitar race/captura onde qualquer um poderia fechar no
 *         instante mais favoravel a um projeto especifico. Governanca decide
 *         quando fechar, dentro ou fora do `roundDuration`.
 *       - Fechar antes do `roundDuration` e permitido (emergencia) e marcado
 *         no evento `RoundClosed.earlyClose = true`. Fechar depois do
 *         `roundDuration` e o fluxo normal, marcado com `earlyClose = false`.
 *       - Nao ha "abrir rodada" — round 0 comeca no constructor; cada
 *         closeRound incrementa e reinicia implicitamente (roundStartedAt
 *         passa a ser `block.timestamp`).
 *
 *      O BurnTracker NAO chama o RewardDistributor ao fechar. Distributor
 *      consome em pull, lendo as views deste contrato (arquitetura v1:
 *      pull-based claim). Evita acoplamento ciclico e falha de um lado
 *      travando o outro.
 *
 *      Dependencias pos-deploy (responsabilidade do deploy script da fase 5):
 *       - CreditToken precisa conceder `BURNER_ROLE` a este contrato. Isso
 *         nao e feito no constructor do BurnTracker porque BurnTracker nao
 *         pode self-grant em outro contrato.
 *       - Apps listados recebem `RECORDER_ROLE` via proposta de listing
 *         aprovada no Governor + Timelock (mesmo caminho do registro no
 *         ProjectRegistry).
 * @custom:security-contact security@web3community.example
 */
contract BurnTracker is AccessControl, ReentrancyGuard {
    // ------------------------------------------------------------------
    // Roles
    // ------------------------------------------------------------------

    /// @notice Role concedida ao `TimelockController`. Pode fechar rodada,
    ///         ajustar `roundDuration` e `maxBurnPerRoundPerProject`.
    bytes32 public constant GOVERNANCE_ROLE = keccak256("GOVERNANCE_ROLE");

    /// @notice Role concedida a cada app listado (via proposta do Governor).
    ///         Autoriza {burnAndRecord}. Revogar a role suspende o app
    ///         imediatamente sem afetar burns passados.
    bytes32 public constant RECORDER_ROLE = keccak256("RECORDER_ROLE");

    // ------------------------------------------------------------------
    // Round duration bounds
    // ------------------------------------------------------------------

    /// @notice Duracao minima permitida de uma rodada (1 dia). Impede que
    ///         governanca configure rodadas micro-curtas que tornariam a
    ///         contabilidade ruidosa demais para rewards.
    // solhint-disable-next-line const-name-snakecase
    uint64 public constant MIN_ROUND_DURATION = 1 days;

    /// @notice Duracao maxima permitida (30 dias). Impede rodadas longas
    ///         demais que atrasariam emissao de rewards e criariam dead
    ///         weight no orcamento.
    // solhint-disable-next-line const-name-snakecase
    uint64 public constant MAX_ROUND_DURATION = 30 days;

    // ------------------------------------------------------------------
    // Immutable dependencies
    // ------------------------------------------------------------------

    /// @notice Token de credito cujo burn e rastreado.
    // solhint-disable-next-line var-name-mixedcase
    CreditToken public immutable CREDIT_TOKEN;

    /// @notice Registry consultado para validar status de projeto (Active).
    // solhint-disable-next-line var-name-mixedcase
    ProjectRegistry public immutable REGISTRY;

    // ------------------------------------------------------------------
    // Round state
    // ------------------------------------------------------------------

    /// @notice Identificador da rodada atual. Comeca em 0 no constructor;
    ///         incrementa em cada {closeRound}.
    uint256 public currentRound;

    /// @notice Timestamp (segundos) em que a rodada atual comecou. Setado
    ///         no constructor e em cada {closeRound}.
    uint64 public roundStartedAt;

    /// @notice Duracao alvo da rodada atual (segundos). Governance-tunable
    ///         via {setRoundDuration}. Alteracoes afetam a rodada atual para
    ///         fins de {getRoundEndsAt}/{isRoundReadyToClose}, mas o
    ///         controle efetivo de close esta em {closeRound} (governanca
    ///         decide).
    uint64 public roundDuration;

    /// @notice Teto de CREDIT queimavel por (round, projectId). Governance-
    ///         tunable. `0` = opt-out (sem limite). Default economico:
    ///         algo como 10M * 1e18, mas o constructor aceita qualquer
    ///         valor para permitir testes locais com caps pequenos.
    uint256 public maxBurnPerRoundPerProject;

    // ------------------------------------------------------------------
    // Accounting
    // ------------------------------------------------------------------

    /// @notice Soma total de CREDIT queimada no `round`.
    mapping(uint256 round => uint256) public totalBurnByRound;

    /// @notice CREDIT queimado no `round` atribuido a `projectId`.
    mapping(uint256 round => mapping(uint256 projectId => uint256)) public burnByRoundProject;

    /// @notice Quantos projetos DISTINTOS tiveram pelo menos 1 burn no `round`.
    ///         Incrementado apenas na primeira gravacao do projeto na rodada.
    ///         RewardDistributor usa isso para detectar "rodada sem burn" (=> 0
    ///         emissao) sem iterar.
    mapping(uint256 round => uint256) public projectsWithBurnCount;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    /// @notice Emitido em cada {burnAndRecord} bem-sucedido.
    /// @param round Rodada em que o burn foi registrado.
    /// @param projectId Projeto ao qual o burn foi atribuido.
    /// @param from Usuario que teve CREDIT queimado.
    /// @param amount Quantidade queimada nesta chamada.
    /// @param newTotalForProject Total acumulado do projeto na rodada apos
    ///                           este burn (conveniencia para indexers).
    event BurnRecorded(
        uint256 indexed round,
        uint256 indexed projectId,
        address indexed from,
        uint256 amount,
        uint256 newTotalForProject
    );

    /// @notice Emitido em {closeRound}.
    /// @param round Rodada que acabou de fechar (valor anterior de `currentRound`).
    /// @param totalBurn Total de CREDIT queimado na rodada fechada.
    /// @param projectsCount Numero de projetos distintos com burn na rodada.
    /// @param closedAt Timestamp (seg) em que a rodada foi fechada.
    /// @param earlyClose `true` se a rodada foi fechada antes de atingir
    ///                   `roundDuration`; `false` caso contrario.
    event RoundClosed(
        uint256 indexed round,
        uint256 totalBurn,
        uint256 projectsCount,
        uint64 closedAt,
        bool earlyClose
    );

    /// @notice Emitido em {setRoundDuration}.
    event RoundDurationUpdated(uint64 oldDuration, uint64 newDuration);

    /// @notice Emitido em {setMaxBurnPerRoundPerProject}.
    event MaxBurnPerRoundPerProjectUpdated(uint256 oldMax, uint256 newMax);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    /// @notice Endereco zero nao e valido.
    error ZeroAddress();

    /// @notice Valor zero nao e permitido em operacoes que exigem > 0.
    error ZeroAmount();

    /// @notice Projeto nao esta em status `Active` (cobre Pending, Probation,
    ///         Removed e inexistente).
    /// @param projectId Projeto consultado.
    error ProjectNotActive(uint256 projectId);

    /// @notice Sanity cap por (round, projectId) seria ultrapassado.
    /// @param projectId Projeto em questao.
    /// @param attempted Total acumulado apos este burn (accumulated + amount).
    /// @param cap `maxBurnPerRoundPerProject` vigente.
    error SanityCapExceeded(uint256 projectId, uint256 attempted, uint256 cap);

    /// @notice `roundDuration` fora da faixa [`MIN_ROUND_DURATION`,
    ///         `MAX_ROUND_DURATION`].
    /// @param provided Valor tentado.
    /// @param min Limite inferior permitido.
    /// @param max Limite superior permitido.
    error InvalidRoundDuration(uint64 provided, uint64 min, uint64 max);

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    /**
     * @notice Cria o tracker apontando para CREDIT e Registry. Round 0 comeca
     *         agora (`roundStartedAt = block.timestamp`).
     * @dev Concede `DEFAULT_ADMIN_ROLE` e `GOVERNANCE_ROLE` a `admin`. Em
     *      producao, `admin` e inicialmente o deployer e o deploy script
     *      transfere `GOVERNANCE_ROLE` ao TimelockController e renuncia
     *      (invariante I4). BURNER_ROLE no CREDIT e RECORDER_ROLE nos apps
     *      sao concedidos fora do constructor (pos-deploy).
     *      Valida:
     *       - `admin`, `creditToken`, `registry` != address(0)
     *       - `initialRoundDuration` em [`MIN_ROUND_DURATION`,
     *         `MAX_ROUND_DURATION`]
     *      `initialSanityCap == 0` e explicitamente aceito (sem limite).
     * @param admin Endereco que recebe admin e governance inicial.
     * @param creditToken Endereco do `CreditToken`.
     * @param registry Endereco do `ProjectRegistry`.
     * @param initialRoundDuration Duracao inicial da rodada (seg).
     * @param initialSanityCap Cap inicial por (round, project). 0 = sem limite.
     */
    constructor(
        address admin,
        address creditToken,
        address registry,
        uint64 initialRoundDuration,
        uint256 initialSanityCap
    ) {
        if (admin == address(0) || creditToken == address(0) || registry == address(0)) {
            revert ZeroAddress();
        }
        if (initialRoundDuration < MIN_ROUND_DURATION || initialRoundDuration > MAX_ROUND_DURATION) {
            revert InvalidRoundDuration(initialRoundDuration, MIN_ROUND_DURATION, MAX_ROUND_DURATION);
        }

        CREDIT_TOKEN = CreditToken(creditToken);
        REGISTRY = ProjectRegistry(registry);

        roundDuration = initialRoundDuration;
        maxBurnPerRoundPerProject = initialSanityCap;
        roundStartedAt = uint64(block.timestamp);

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(GOVERNANCE_ROLE, admin);
    }

    // ------------------------------------------------------------------
    // Core — state-changing
    // ------------------------------------------------------------------

    /**
     * @notice Queima `amount` de CREDIT do saldo de `from` e registra o burn
     *         no par (rodada atual, `projectId`) atomicamente. Chamado por
     *         cada app (portador de `RECORDER_ROLE`) quando o usuario consome
     *         um servico pago.
     * @dev Fluxo (Checks → Effects → Interactions):
     *        1. Checks:
     *           - `RECORDER_ROLE` (modifier).
     *           - `projectId` Active no Registry.
     *           - `from != address(0)`.
     *           - `amount > 0`.
     *           - Sanity cap: `accumulated + amount <= cap` (se cap > 0).
     *        2. Effects:
     *           - `burnByRoundProject[round][projectId] += amount`.
     *           - `totalBurnByRound[round] += amount`.
     *           - `projectsWithBurnCount[round]` += 1 SE este for o primeiro
     *             burn do projeto na rodada (accumulated era 0).
     *        3. Interactions:
     *           - `CreditToken.burnByRole(from, amount, tag)`.
     *      **Por que effects antes do burn?** O padrao CEI classico pede
     *      effects-antes-interactions para blindar contra reentrancia. Como
     *      `burnByRole` e do nosso proprio CreditToken e usa `_burn` nativo
     *      sem callback, nao ha vetor de reentrancia real — mas seguir CEI
     *      mantem consistencia com o restante do codebase e blinda contra
     *      regressoes futuras. Se o burn reverter (ex.: saldo insuficiente),
     *      toda a tx reverte e nenhum estado persiste — state-machine
     *      consistente.
     *      `nonReentrant` aplicado como defesa-em-profundidade (recorders
     *      sao apps terceiros, nao controlamos o bytecode deles).
     *      O parametro `tag` enviado ao CreditToken.burnByRole e fixado em
     *      `"burnTracker"` para auditabilidade off-chain do event log do
     *      CREDIT — o tag rico (projeto, round) ja e coberto pelo evento
     *      `BurnRecorded` deste contrato.
     * @param projectId Projeto ao qual atribuir o burn (deve estar Active).
     * @param from Usuario cujo CREDIT sera queimado.
     * @param amount Quantidade de CREDIT a queimar (> 0).
     */
    function burnAndRecord(
        uint256 projectId,
        address from,
        uint256 amount
    ) external onlyRole(RECORDER_ROLE) nonReentrant {
        if (from == address(0)) {
            revert ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (!REGISTRY.isActive(projectId)) {
            revert ProjectNotActive(projectId);
        }

        uint256 round = currentRound;
        uint256 accumulated = burnByRoundProject[round][projectId];

        uint256 cap = maxBurnPerRoundPerProject;
        uint256 newTotalForProject = accumulated + amount;
        if (cap != 0 && newTotalForProject > cap) {
            revert SanityCapExceeded(projectId, newTotalForProject, cap);
        }

        // Effects.
        burnByRoundProject[round][projectId] = newTotalForProject;
        totalBurnByRound[round] += amount;
        if (accumulated == 0) {
            // Primeiro burn deste projeto na rodada — conta o projeto.
            unchecked {
                // Bound: <= numero de projetos no Registry. Nunca overflow.
                projectsWithBurnCount[round] = projectsWithBurnCount[round] + 1;
            }
        }

        emit BurnRecorded(round, projectId, from, amount, newTotalForProject);

        // Interaction: queima o CREDIT. Reverte se saldo insuficiente (ERC-20)
        // ou se o tracker perder BURNER_ROLE (AccessControl).
        CREDIT_TOKEN.burnByRole(from, amount, "burnTracker");
    }

    /**
     * @notice Fecha a rodada atual e abre a proxima. Incrementa
     *         `currentRound`, reseta `roundStartedAt = block.timestamp`.
     *         Accounting das rodadas fechadas e preservado on-chain
     *         indefinidamente (cada rodada tem seu proprio indice nos
     *         mappings).
     * @dev Restrita a `GOVERNANCE_ROLE` (Timelock em producao).
     *      Pode ser chamada a qualquer momento:
     *       - Se `block.timestamp >= roundStartedAt + roundDuration`,
     *         emite `RoundClosed` com `earlyClose = false` (fluxo normal).
     *       - Caso contrario, emite com `earlyClose = true` (emergencia /
     *         decisao governamental antecipada).
     *      Nao chama RewardDistributor — Distributor consome em pull via
     *      `getTotalBurnForRound` / `getBurnForProjectInRound` quando o
     *      proximo batch de rewards for executado.
     *      Empty round (sem nenhum burn) e permitido: o evento sai com
     *      totalBurn=0 e projectsCount=0; documenta explicitamente que
     *      rodada correu sem consumo.
     */
    function closeRound() external onlyRole(GOVERNANCE_ROLE) {
        uint256 round = currentRound;
        uint64 nowTs = uint64(block.timestamp);
        uint64 endsAt = roundStartedAt + roundDuration;
        bool earlyClose = nowTs < endsAt;

        uint256 totalBurn = totalBurnByRound[round];
        uint256 projectsCount = projectsWithBurnCount[round];

        // Effects.
        unchecked {
            // `currentRound` e uint256 — overflow teorico apos 2^256 rodadas.
            // Irrealista: 2^256 segundos >> idade do universo.
            currentRound = round + 1;
        }
        roundStartedAt = nowTs;

        emit RoundClosed(round, totalBurn, projectsCount, nowTs, earlyClose);
    }

    /**
     * @notice Atualiza a duracao alvo da rodada. Deve estar em
     *         [`MIN_ROUND_DURATION`, `MAX_ROUND_DURATION`].
     * @dev Restrita a `GOVERNANCE_ROLE`. A mudanca afeta a rodada atual
     *      para os views {getRoundEndsAt}/{isRoundReadyToClose} (e portanto
     *      quando a rodada sera considerada "pronta pra fechar" pelo
     *      proximo call de {closeRound}) — nao altera accounting de
     *      rodadas ja fechadas.
     * @param newDuration Nova duracao em segundos.
     */
    function setRoundDuration(uint64 newDuration) external onlyRole(GOVERNANCE_ROLE) {
        if (newDuration < MIN_ROUND_DURATION || newDuration > MAX_ROUND_DURATION) {
            revert InvalidRoundDuration(newDuration, MIN_ROUND_DURATION, MAX_ROUND_DURATION);
        }
        uint64 old = roundDuration;
        roundDuration = newDuration;
        emit RoundDurationUpdated(old, newDuration);
    }

    /**
     * @notice Atualiza o sanity cap por (round, project).
     * @dev Restrita a `GOVERNANCE_ROLE`. `0` desativa o limite (opt-out).
     *      A checagem em {burnAndRecord} usa o valor vigente no momento do
     *      burn — nao e retroativa. Se o cap for reduzido abaixo do
     *      acumulado atual de algum projeto, novos burns nesse projeto
     *      naquela rodada sao bloqueados imediatamente, mas o acumulado
     *      ja registrado permanece (historia preservada).
     * @param newMax Novo cap (wei). 0 = sem limite.
     */
    function setMaxBurnPerRoundPerProject(uint256 newMax) external onlyRole(GOVERNANCE_ROLE) {
        uint256 old = maxBurnPerRoundPerProject;
        maxBurnPerRoundPerProject = newMax;
        emit MaxBurnPerRoundPerProjectUpdated(old, newMax);
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------

    /// @notice Sinonimo de `currentRound` (ergonomia de API — Distributor
    ///         pode preferir um getter nomeado).
    function getCurrentRound() external view returns (uint256) {
        return currentRound;
    }

    /// @notice Timestamp (seg) em que a rodada atual "termina" conforme a
    ///         duracao vigente. Uso consultivo; o close efetivo acontece
    ///         em {closeRound}.
    function getRoundEndsAt() external view returns (uint64) {
        return roundStartedAt + roundDuration;
    }

    /// @notice `true` se a rodada atual ja atingiu ou passou da sua
    ///         duracao alvo (pronta para close normal).
    function isRoundReadyToClose() external view returns (bool) {
        return block.timestamp >= uint256(roundStartedAt) + uint256(roundDuration);
    }

    /// @notice Valor de `burnByRoundProject[round][projectId]` — wrapper
    ///         explicito para callers que preferem uma API nomeada.
    function getBurnForProjectInRound(uint256 round, uint256 projectId) external view returns (uint256) {
        return burnByRoundProject[round][projectId];
    }

    /// @notice Valor de `totalBurnByRound[round]` — wrapper nomeado.
    function getTotalBurnForRound(uint256 round) external view returns (uint256) {
        return totalBurnByRound[round];
    }
}

contracts/CommunityGovernor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Governor} from "@openzeppelin/contracts/governance/Governor.sol";
import {GovernorSettings} from "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";
import {GovernorCountingSimple} from "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";
import {GovernorVotes} from "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";
// solhint-disable-next-line max-line-length
import {GovernorVotesQuorumFraction} from "@openzeppelin/contracts/governance/extensions/GovernorVotesQuorumFraction.sol";
import {GovernorTimelockControl} from "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";
import {IVotes} from "@openzeppelin/contracts/governance/utils/IVotes.sol";
import {TimelockController} from "@openzeppelin/contracts/governance/TimelockController.sol";

/**
 * @title CommunityGovernor
 * @notice Governor canonico da DAO Web3Community, composto pelo stack OZ 5.0.x:
 *         {Governor} + {GovernorSettings} + {GovernorCountingSimple} +
 *         {GovernorVotes} + {GovernorVotesQuorumFraction} +
 *         {GovernorTimelockControl}.
 *
 *         Voting power e lida do {GovernanceToken} (ERC20Votes), garantindo que
 *         flash loans nao influenciem propostas (invariante I5). Toda execucao
 *         bem-sucedida e roteada via {CommunityTimelock}, que aplica delay e
 *         mantem os contratos economicos isolados de chamadas ad-hoc do Governor.
 *
 * @dev Decisoes de parametro (ajustaveis depois via {setVotingDelay},
 *      {setVotingPeriod}, {setProposalThreshold}, {updateQuorumNumerator},
 *      todas `onlyGovernance`):
 *
 *      PRODUCAO (sugestao):
 *          votingDelay    = 7200 blocks  (~1 dia @ 12s/block)
 *          votingPeriod   = 50400 blocks (~7 dias @ 12s/block)
 *          threshold      = 10_000 * 1e18 GOV (0,01% do cap) — baixo para nao
 *                           calcificar governanca, mas > 0 para bloquear proposta
 *                           spam vinda de contas sem skin in the game
 *          quorumFraction = 4%           (padrao OZ/Compound; balanceia
 *                           participacao real vs risco de captura por minoria)
 *
 *      DEV / TESTES:
 *          votingDelay    = 1 block
 *          votingPeriod   = 50 blocks
 *          threshold      = 10_000 * 1e18 GOV (mantem o mesmo para cobrir o
 *                           guard em teste unitario)
 *          quorumFraction = 4%
 *
 *      O nome "CommunityGovernor" e usado como `name` do EIP-712 no constructor
 *      do {Governor}; mudar o nome quebra o domain separator e invalida
 *      assinaturas previas de {castVoteBySig} / {castVoteWithReasonAndParamsBySig}.
 *      Nunca renomear sem migracao.
 *
 *      Clock mode: delegamos ao token via {GovernorVotes.clock} — {GovernanceToken}
 *      nao sobrescreve `clock()`, entao a fallback do ERC20Votes retorna
 *      `block.number`, e o Governor passa a operar em numero de blocos.
 *      Toda a aritmetica de delay/period aqui e em BLOCKS.
 *
 *      Invariantes atendidas:
 *      - I4: voting power isolada em `token()`; execucao via Timelock; nenhuma
 *        funcao bypass admin.
 *      - I5: {IERC5805.getPastVotes} via ERC20Votes — snapshot imune a flash
 *        loans no bloco do voto.
 *      - I7: o Governor e o unico autorizado a propor acoes que o Timelock
 *        executa contra {ProjectRegistry}, entao registro/alteracao de
 *        projetos obriga proposta aprovada.
 *
 *      Overrides obrigatorios:
 *      - {votingDelay}, {votingPeriod}, {proposalThreshold}: hierarquia exige
 *        resolver Governor vs GovernorSettings.
 *      - {quorum}: resolve Governor vs GovernorVotesQuorumFraction.
 *      - {state}, {proposalNeedsQueuing}, {_queueOperations},
 *        {_executeOperations}, {_cancel}, {_executor}: resolve Governor vs
 *        GovernorTimelockControl.
 *      - {supportsInterface}: nao e necessario override composto aqui — no OZ
 *        5.0.2 apenas {Governor} define; deixamos como herdado.
 *
 * @custom:security-contact security@web3community.example
 */
contract CommunityGovernor is
    Governor,
    GovernorSettings,
    GovernorCountingSimple,
    GovernorVotes,
    GovernorVotesQuorumFraction,
    GovernorTimelockControl
{
    /**
     * @notice Cria o CommunityGovernor amarrado a um token ERC20Votes e a um
     *         Timelock. O nome "CommunityGovernor" trava o domain separator do
     *         EIP-712 — nao altere em upgrades.
     * @dev Parametros sao imediatamente setados via {GovernorSettings} e
     *      {GovernorVotesQuorumFraction}; podem ser alterados apos deploy
     *      apenas via proposta governance (onlyGovernance dos respectivos
     *      setters), ou seja, passando pelo Timelock.
     *      Guards implicitos OZ:
     *      - `GovernorInvalidVotingPeriod(0)` reverte se `initialVotingPeriod == 0`
     *        ({GovernorSettings._setVotingPeriod}).
     *      - `GovernorInvalidQuorumFraction(n, 100)` reverte se
     *        `initialQuorumNumerator > 100`
     *        ({GovernorVotesQuorumFraction._updateQuorumNumerator}).
     * @param token Token ERC20Votes fonte de voting power (GovernanceToken).
     * @param timelock Timelock que executa as propostas aprovadas.
     * @param initialVotingDelay Delay em blocos entre propor e abrir a votacao.
     * @param initialVotingPeriod Duracao da votacao em blocos (>0 obrigatorio).
     * @param initialProposalThreshold Minimo de voting power delegado para
     *                                 propor (em wei-equivalent do GOV).
     * @param initialQuorumNumerator Numerador da fracao de quorum sobre 100
     *                               (4 = 4%).
     */
    constructor(
        IVotes token,
        TimelockController timelock,
        uint48 initialVotingDelay,
        uint32 initialVotingPeriod,
        uint256 initialProposalThreshold,
        uint256 initialQuorumNumerator
    )
        Governor("CommunityGovernor")
        GovernorSettings(initialVotingDelay, initialVotingPeriod, initialProposalThreshold)
        GovernorVotes(token)
        GovernorVotesQuorumFraction(initialQuorumNumerator)
        GovernorTimelockControl(timelock)
    {}

    // ------------------------------------------------------------------
    // Overrides requeridos pela multipla heranca (Governor vs extensoes)
    // ------------------------------------------------------------------

    /**
     * @notice Retorna o delay (em blocos) aplicado entre a criacao de uma
     *         proposta e a abertura da janela de votacao.
     * @dev Resolve conflito Governor vs GovernorSettings — o valor efetivo
     *      vem do {GovernorSettings}.
     */
    function votingDelay() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingDelay();
    }

    /**
     * @notice Retorna a duracao (em blocos) da janela de votacao de uma
     *         proposta.
     * @dev Resolve conflito Governor vs GovernorSettings.
     */
    function votingPeriod() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingPeriod();
    }

    /**
     * @notice Retorna o minimo de voting power delegado exigido para criar uma
     *         proposta.
     * @dev Resolve conflito Governor vs GovernorSettings. Mantem 10_000e18 GOV
     *      como patamar para evitar spam sem calcificar.
     */
    function proposalThreshold() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.proposalThreshold();
    }

    /**
     * @notice Quantidade absoluta de votos necessaria para atingir quorum
     *         num dado `timepoint` (normalmente o bloco de snapshot da
     *         proposta).
     * @dev Resolve conflito Governor vs GovernorVotesQuorumFraction. Usa o
     *      `getPastTotalSupply` do ERC20Votes para garantir snapshot — evita
     *      dependencia do supply atual e, por tabela, ataques que diluam
     *      supply pos-proposal para alcancar quorum artificialmente.
     */
    function quorum(uint256 timepoint) public view override(Governor, GovernorVotesQuorumFraction) returns (uint256) {
        return super.quorum(timepoint);
    }

    /**
     * @notice Estado atual da proposta `proposalId`. Pode ser Pending, Active,
     *         Canceled, Defeated, Succeeded, Queued, Expired ou Executed.
     * @dev Resolve conflito Governor vs GovernorTimelockControl — este ultimo
     *      reescreve para refletir o estado do Timelock apos o queue
     *      (Queued / Executed / Canceled).
     */
    function state(uint256 proposalId) public view override(Governor, GovernorTimelockControl) returns (ProposalState) {
        return super.state(proposalId);
    }

    /**
     * @notice Indica se uma proposta precisa passar por {queue} antes de
     *         {execute}. Com Timelock acoplado, sempre `true`.
     * @dev Resolve conflito Governor vs GovernorTimelockControl.
     */
    function proposalNeedsQueuing(
        uint256 proposalId
    ) public view override(Governor, GovernorTimelockControl) returns (bool) {
        return super.proposalNeedsQueuing(proposalId);
    }

    /**
     * @dev Hook interno de queue. Roteado para o Timelock via
     *      {GovernorTimelockControl._queueOperations}.
     */
    function _queueOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint48) {
        return super._queueOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    /**
     * @dev Hook interno de execucao. Roteado para o Timelock via
     *      {GovernorTimelockControl._executeOperations}.
     */
    function _executeOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) {
        super._executeOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    /**
     * @dev Hook interno de cancelamento. Cancela a proposta no Governor e, se
     *      ja estiver enfileirada, no Timelock. Apenas atingivel pelo flow
     *      {cancel(...)} publico (proposer) ou via onlyGovernance em extensoes.
     */
    function _cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint256) {
        return super._cancel(targets, values, calldatas, descriptionHash);
    }

    /**
     * @dev Endereco que executa efetivamente as chamadas aprovadas — o
     *      Timelock neste stack. Usado pelo modifier `onlyGovernance` para
     *      saber quem pode chamar funcoes protegidas.
     */
    function _executor() internal view override(Governor, GovernorTimelockControl) returns (address) {
        return super._executor();
    }
}

contracts/CreditToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title CreditToken (CREDIT)
 * @notice Token utilitario ERC-20 da Web3Community. Queimado no consumo dentro da
 *         plataforma (pagamentos de features, fees dos apps) e cunhado pelo
 *         `RewardDistributor` em rodadas. Sem supply cap hardcoded: a inflacao
 *         e controlada economicamente por quem detem `MINTER_ROLE` (o distributor,
 *         que por sua vez aplica cap por rodada — invariante I3 vive la, nao aqui).
 * @dev Invariantes atendidas nesta unidade:
 *      - I2: Burn no consumo e suportado em 3 caminhos complementares:
 *            (a) {burn}            — holder queima o proprio saldo;
 *            (b) {burnFrom}        — terceiros queimam com allowance (ERC20Burnable);
 *            (c) {burnByRole}      — portadores de {BURNER_ROLE} queimam SEM allowance.
 *            O caminho (c) existe para permitir que o futuro `BurnTracker` execute
 *            `burnAndRecord` atomicamente em um unico tx, no contexto de um app
 *            pago pelo usuario (UX: usuario assina 1 tx no app, nao um approve + burn).
 *            Ele e seguro porque `BURNER_ROLE` so e concedido via TimelockController
 *            apos proposta aprovada na DAO (invariante I7 do registry), e a role
 *            pode ser revogada pelo admin (eventualmente o proprio Timelock) a
 *            qualquer momento.
 *      - Supply elastico: nao ha cap. Mints adicionais sao sempre possiveis desde
 *            que quem chama tenha `MINTER_ROLE`. O cap por rodada e do distributor.
 *      Nao herda {ERC20Votes}: CREDIT nao vota (so GOV vota). Nao herda
 *      {ERC20Permit}: no v1 optamos por superficie minima. Consumo via
 *      `FeeRouter.pay()` usa ou (1) allowance + `burnFrom`, ou (2) `burnByRole`
 *      atomico pelo `BurnTracker`. Se permit virar necessario em v2, basta
 *      adicionar a extensao mantendo storage layout.
 *      Genesis de 10M pre-cunhado NAO acontece no constructor. Em vez disso
 *      expomos {mintGenesis}, chamada uma unica vez pelo admin durante o deploy
 *      (flag {genesisMinted} one-shot). Isso mantem o constructor puro, permite
 *      que o deploy script escolha o destinatario (tesouraria) sem hardcode e
 *      deixa o contrato auditavel sem depender de parametros de construtor.
 * @custom:security-contact security@web3community.example
 */
contract CreditToken is ERC20, ERC20Burnable, AccessControl {
    /// @notice Role autorizada a cunhar CREDIT via {mint}. Concedida pelo admin
    ///         ao `RewardDistributor` na fase 4 do deploy.
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @notice Role autorizada a queimar CREDIT de qualquer holder via
    ///         {burnByRole} SEM consumir allowance. Concedida pelo admin
    ///         (idealmente o Timelock) ao `BurnTracker` / `FeeRouter` da fase 3.
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    /// @notice `true` apos a primeira execucao bem-sucedida de {mintGenesis}.
    ///         Flag one-shot que impede o admin de re-executar o genesis mint
    ///         mesmo que detenha `DEFAULT_ADMIN_ROLE`.
    bool public genesisMinted;

    /// @notice Emitido no mint inicial (genesis) pre-cunhado para a tesouraria.
    /// @param to Destinatario do genesis (geralmente a tesouraria da DAO).
    /// @param amount Quantidade cunhada (em unidades minimas, 1e18 precision).
    event GenesisMinted(address indexed to, uint256 amount);

    /// @notice Emitido em todo {mint} bem-sucedido feito por um `MINTER_ROLE`.
    /// @param to Destinatario dos tokens cunhados.
    /// @param amount Quantidade cunhada (em unidades minimas).
    /// @param tag Rotulo off-chain para rastrear a origem economica
    ///            (ex.: "rewardRound:42", "retroActive:q2", "airdrop:launch").
    event Minted(address indexed to, uint256 amount, string tag);

    /// @notice Emitido em todo {burnByRole} bem-sucedido.
    /// @param operator Endereco com `BURNER_ROLE` que executou a queima.
    /// @param from Endereco cujo saldo foi queimado (usuario final).
    /// @param amount Quantidade queimada.
    /// @param tag Rotulo off-chain para rastreio (ex.: "feeRouter:pay",
    ///            "subscription:renew").
    event BurnedByRole(address indexed operator, address indexed from, uint256 amount, string tag);

    /// @notice Endereco zero nao e valido como destinatario/alvo.
    error ZeroAddress();

    /// @notice Valor zero nao e permitido em operacoes que exigem amount > 0.
    error ZeroAmount();

    /// @notice {mintGenesis} so pode ser executado uma unica vez.
    error GenesisAlreadyMinted();

    /**
     * @notice Cria o token de credito da Web3Community.
     * @dev O admin inicial recebe `DEFAULT_ADMIN_ROLE` e pode conceder
     *      `MINTER_ROLE` / `BURNER_ROLE` posteriormente. Nenhum token e
     *      cunhado no constructor — `totalSupply()` comeca em 0. Para o
     *      genesis de 10M, o deploy script chama {mintGenesis} em seguida.
     *      O admin inicial deve ser o deployer em local/testnet e o
     *      TimelockController em producao (invariante I4 aplicada fora
     *      deste contrato, via `grantRole` + `renounceRole` no script de
     *      deploy).
     * @param name_ Nome ERC-20 legivel (ex.: "Web3Community Credit").
     * @param symbol_ Simbolo ERC-20 curto (ex.: "CREDIT").
     * @param initialAdmin Endereco que recebe `DEFAULT_ADMIN_ROLE`.
     */
    constructor(string memory name_, string memory symbol_, address initialAdmin) ERC20(name_, symbol_) {
        if (initialAdmin == address(0)) {
            revert ZeroAddress();
        }
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
    }

    /**
     * @notice Cunha o supply de genesis (10M) para `to`. Pode ser executado UMA
     *         UNICA VEZ; chamadas subsequentes revertem com {GenesisAlreadyMinted}.
     * @dev Restrita a `DEFAULT_ADMIN_ROLE`. Intencionalmente o amount e parametro
     *      (nao hardcoded) para que o script de deploy tenha controle explicito
     *      do numero exato e para facilitar auditoria em chain — a quantidade
     *      real e assinada no evento {GenesisMinted} e visivel off-chain antes
     *      de qualquer outra operacao do token.
     *      NAO consome `MINTER_ROLE` — o caminho do genesis e separado do
     *      caminho operacional para nao exigir que o admin tambem seja minter.
     * @param to Destinatario do genesis (tesouraria da DAO).
     * @param amount Quantidade a cunhar (em unidades minimas).
     */
    function mintGenesis(address to, uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (genesisMinted) {
            revert GenesisAlreadyMinted();
        }
        if (to == address(0)) {
            revert ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        genesisMinted = true;
        _mint(to, amount);
        emit GenesisMinted(to, amount);
    }

    /**
     * @notice Cunha `amount` tokens para `to`. Restrita a `MINTER_ROLE`.
     * @dev Em producao o unico endereco com `MINTER_ROLE` e o `RewardDistributor`,
     *      que aplica cap por rodada antes de chamar. Este contrato NAO valida
     *      cap — supply elastico por design (invariante I3 fica no distributor).
     *      O parametro `tag` e so registro off-chain (via evento) e serve para
     *      auditar a origem economica de cada mint (ex.: id da rodada, nome do
     *      airdrop). Nao afeta contabilidade on-chain.
     *      Reverte com {ZeroAddress} se `to == address(0)` e {ZeroAmount} se
     *      `amount == 0`.
     * @param to Destinatario dos tokens.
     * @param amount Quantidade a cunhar (em unidades minimas).
     * @param tag Rotulo descritivo (opcional; apenas evento).
     */
    function mint(address to, uint256 amount, string calldata tag) external onlyRole(MINTER_ROLE) {
        if (to == address(0)) {
            revert ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        _mint(to, amount);
        emit Minted(to, amount, tag);
    }

    /**
     * @notice Queima `amount` tokens do saldo de `from` SEM consumir allowance.
     *         Restrita a `BURNER_ROLE`.
     * @dev *Por que nao usar {burnFrom} com allowance aqui?* Porque o consumo
     *      dentro da plataforma acontece em um unico tx disparado pelo app
     *      (ex.: `FeeRouter.pay()` que chama `BurnTracker.burnAndRecord()` que
     *      chama `CreditToken.burnByRole()`). Exigir approve previo quebraria
     *      atomicidade (2 txs do usuario) e criaria janela de front-run entre
     *      approve e burn. A mitigacao desta escolha e o gating por role:
     *      `BURNER_ROLE` so e concedido a contratos especificos apos proposta
     *      aprovada na DAO (via Timelock), e a role pode ser revogada a
     *      qualquer momento se um contrato com a role for descoberto
     *      comprometido. Usuarios que quiserem o fluxo "consinto queima
     *      explicitamente" usam {burnFrom} com allowance — esse caminho
     *      continua disponivel via ERC20Burnable.
     *      CEI aplicada: checagens primeiro, efeito (_burn) depois, sem
     *      interacoes externas. `_burn` do ERC-20 ja decrementa balance e
     *      totalSupply, e reverte com {ERC20InsufficientBalance} se o saldo
     *      for menor que `amount`.
     * @param from Endereco cujo saldo sera queimado.
     * @param amount Quantidade a queimar.
     * @param tag Rotulo off-chain (ex.: "feeRouter:pay", "sub:monthly").
     */
    function burnByRole(address from, uint256 amount, string calldata tag) external onlyRole(BURNER_ROLE) {
        if (from == address(0)) {
            revert ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        _burn(from, amount);
        emit BurnedByRole(_msgSender(), from, amount, tag);
    }
}

contracts/FeeRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {CreditToken} from "./CreditToken.sol";
import {BurnTracker} from "./BurnTracker.sol";
import {ProjectRegistry} from "./ProjectRegistry.sol";
import {Treasury} from "./Treasury.sol";

/**
 * @title FeeRouter
 * @notice Interface unica de pagamento entre apps do ecossistema e o protocolo.
 *         Todo consumo de CREDIT feito por usuarios finais dentro de um app
 *         listado passa por {pay}, que divide o valor em 3 destinos conforme
 *         split configuravel:
 *          1. `burnBps` e queimado via {BurnTracker.burnAndRecord} —
 *             alimenta a metrica de burn por projeto usada pelo
 *             `RewardDistributor` na proxima rodada.
 *          2. `treasuryBps` e transferido ao `Treasury` multi-ativo da DAO.
 *          3. `rebateBps` e transferido ao `appRecipient` do projeto (rebate
 *             de revenue share para o app).
 *         O split default global e 95/0/5 (95% burn / 0% treasury / 5% app),
 *         coerente com a decisao economica de "venda direta de CREDIT + 5%
 *         revenue share do burn pra apps". Splits podem ser substituidos
 *         por-projeto via governanca (`setProjectSplit`), e o recipient de
 *         rebate por-projeto e setavel pelo owner (`setAppRecipient`).
 * @dev Invariantes economicas atendidas nesta unidade:
 *      - I2 (burn no consumo): toda chamada {pay} que tenha `burnBps > 0`
 *        atomicamente queima a fatia via {BurnTracker.burnAndRecord}, que
 *        por sua vez chama {CreditToken.burnByRole} (_burn nativo, decrementa
 *        totalSupply). Nenhum caminho de {pay} desvia CREDIT queimado para
 *        dead-address, tesouraria ou re-mint.
 *      - I4 (governanca via Timelock): setters economicos (`setDefaultSplit`,
 *        `setProjectSplit`, `clearProjectSplit`) sao `onlyRole(GOVERNANCE_ROLE)`;
 *        em producao `GOVERNANCE_ROLE` e concedida exclusivamente ao
 *        `TimelockController`. `DEFAULT_ADMIN_ROLE` existe apenas para
 *        conceder/revogar roles (padrao OZ AccessControl); o deploy script
 *        transfere ambos ao Timelock e renuncia. {setAppRecipient} e
 *        owner-gated (analogo ao {updateMetadata} do Registry) porque
 *        rotacao do endereco de rebate e operacional e nao justifica ciclo
 *        completo de proposta/voto.
 *      - I7 (projetos via Registry): {pay} revalida `REGISTRY.isActive` cedo
 *        e reverte com {ProjectNotActive} em qualquer status != Active
 *        (Pending, Probation punitiva, Removed, inexistente). Dupla
 *        validacao com o {BurnTracker.burnAndRecord} — intencional:
 *        permite que treasury e rebate tambem sejam bloqueados sem depender
 *        do burn ser > 0.
 *
 *      Desenho deliberado:
 *      - {pay} e PUBLICA. Quem chama e irrelevante desde que `user` tenha
 *        aprovado o FeeRouter previamente. Isso habilita UX flexivel:
 *        apps podem chamar em nome do usuario (meta-tx-like com approve
 *        previo), smart wallets podem chamar direto, UIs podem chamar
 *        diretamente, etc. O payer economico e SEMPRE `user` (puxado via
 *        `transferFrom`); `msg.sender` e apenas o iniciador da tx.
 *      - Dust handling: o residuo `amount - burned - toTreasury` vai
 *        integralmente para o rebate do app. Isso evita perda de wei por
 *        arredondamento em divisoes nao-exatas (a soma final sempre
 *        reconstitui `amount`). Consequencia: em splits com `burnBps +
 *        treasuryBps + rebateBps == 10_000`, o app pode receber 1-2 wei
 *        a mais que o calculo nominal — aceitavel e auditavel.
 *      - Override por projeto usa FLAG `hasProjectSplit` separada do
 *        struct para distinguir "override nao setado" de "override com
 *        zeros validos". Sem flag, um split `{10000, 0, 0}` seria
 *        ambiguo com "sem override".
 *      - {setAppRecipient} com `address(0)` reseta para lookup dinamico
 *        em `REGISTRY.getProject(projectId).owner`. Consequencia desejada:
 *        se o owner transferir o projeto via Registry, o recipient default
 *        acompanha automaticamente sem exigir re-configuracao manual.
 *      - SEM SWEEP no v1. O FeeRouter nao custodia CREDIT entre chamadas —
 *        cada {pay} e atomico (recebe, distribui, queima e termina com
 *        saldo 0). Se alguma anomalia (ex.: token enviado diretamente por
 *        engano) deixar fundos presos, a remediacao e via upgrade/migration
 *        proposto pelo Governor. Adicionar sweep agora criaria superficie
 *        de centralizacao que a DAO prefere nao ter.
 *
 *      Reentrancia:
 *      - {pay} tem multiplos external calls: `credit.transferFrom` (entrada),
 *        `credit.transfer` (rebate), `credit.transfer` (treasury),
 *        `credit.approve` + `burnTracker.burnAndRecord` (burn). Embora
 *        `CreditToken` seja ERC-20 confiavel sem hooks de callback e o
 *        `BurnTracker.burnAndRecord` seja `nonReentrant`, aplicamos
 *        `nonReentrant` em {pay} como defesa-em-profundidade: protege
 *        contra regressoes futuras (ex.: se um dia CREDIT adicionar
 *        ERC-777-like hooks, ou se {BurnTracker} mudar).
 *      - Pattern CEI: checagens primeiro, depois transfer de entrada,
 *        depois distribuicoes. `approve` + `burnAndRecord` sao executados
 *        POR ULTIMO — qualquer reentrada via `burnAndRecord` encontra
 *        guard ativo e reverte.
 *
 *      Dependencias pos-deploy (responsabilidade do deploy script da fase 5):
 *       - {BurnTracker.grantRole(RECORDER_ROLE, feeRouter)} — sem isso,
 *         {pay} reverte em qualquer chamada com `burnBps > 0`. Essa role e
 *         concedida via proposta aprovada no Governor + execucao do Timelock.
 *       - Apps documentarem UX de approval: o usuario precisa ter feito
 *         `CREDIT.approve(feeRouter, amount)` antes de {pay} ser chamado.
 * @custom:security-contact security@web3community.example
 */
contract FeeRouter is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------

    /// @notice Configuracao de split de um pagamento. Os 3 campos sao em
    ///         basis points (1 bp = 0.01%) e devem somar EXATAMENTE 10_000.
    /// @param burnBps Fatia queimada via {BurnTracker.burnAndRecord}.
    /// @param treasuryBps Fatia transferida ao {Treasury}.
    /// @param rebateBps Fatia transferida ao app (`appRecipient`).
    struct Split {
        uint16 burnBps;
        uint16 treasuryBps;
        uint16 rebateBps;
    }

    // ------------------------------------------------------------------
    // Roles
    // ------------------------------------------------------------------

    /// @notice Role concedida ao `TimelockController` em producao. Unica role
    ///         capaz de ajustar `defaultSplit` e `projectSplit` (overrides).
    bytes32 public constant GOVERNANCE_ROLE = keccak256("GOVERNANCE_ROLE");

    /// @dev Denominador dos basis points. Usado na validacao de soma e nas
    ///      divisoes proporcionais em {pay}/{quote}.
    // solhint-disable-next-line const-name-snakecase
    uint256 private constant _BPS_DENOMINATOR = 10_000;

    // ------------------------------------------------------------------
    // Immutable dependencies
    // ------------------------------------------------------------------

    /// @notice Token de credito movido e queimado nesta rota de fees.
    // solhint-disable-next-line var-name-mixedcase
    CreditToken public immutable CREDIT;

    /// @notice Tracker responsavel por queimar o CREDIT e registrar burn por
    ///         projeto na rodada atual.
    // solhint-disable-next-line var-name-mixedcase
    BurnTracker public immutable BURN_TRACKER;

    /// @notice Registry consultado para validar status (`isActive`) e
    ///         resolver owner default do rebate.
    // solhint-disable-next-line var-name-mixedcase
    ProjectRegistry public immutable REGISTRY;

    /// @notice Cofre multi-ativo que recebe a fatia `treasuryBps` do split.
    // solhint-disable-next-line var-name-mixedcase
    Treasury public immutable TREASURY;

    // ------------------------------------------------------------------
    // Storage — split config
    // ------------------------------------------------------------------

    /// @notice Split global default aplicado a projetos sem override.
    ///         Seed inicial 95/0/5 (confirmado na decisao economica).
    Split public defaultSplit;

    /// @notice Override por-projeto. Use {hasProjectSplit} para saber se
    ///         o override existe (distinguir "nao setado" de "zeros validos").
    mapping(uint256 projectId => Split) public projectSplit;

    /// @notice Flag que sinaliza existencia de override em {projectSplit}.
    ///         Setada em {setProjectSplit}, limpa em {clearProjectSplit}.
    mapping(uint256 projectId => bool) public hasProjectSplit;

    /// @notice Destinatario explicito da fatia de rebate por projeto.
    ///         `address(0)` significa "usar `project.owner` do Registry"
    ///         (lookup dinamico — segue transferencias de ownership).
    mapping(uint256 projectId => address) public appRecipient;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    /// @notice Emitido a cada {pay} bem-sucedido.
    /// @param projectId Projeto ao qual o pagamento foi atribuido.
    /// @param user Usuario economico (de quem o CREDIT saiu via `transferFrom`).
    /// @param payer Iniciador da tx (`msg.sender`).
    /// @param amount Valor total do pagamento (em wei de CREDIT).
    /// @param burned Fatia queimada via BurnTracker.
    /// @param toTreasury Fatia transferida ao Treasury.
    /// @param toApp Fatia transferida ao `appRecipient` efetivo.
    /// @param recipient Endereco que recebeu `toApp` (override ou owner).
    event Paid(
        uint256 indexed projectId,
        address indexed user,
        address indexed payer,
        uint256 amount,
        uint256 burned,
        uint256 toTreasury,
        uint256 toApp,
        address recipient
    );

    /// @notice Emitido em {setDefaultSplit}.
    /// @param oldSplit Split anterior.
    /// @param newSplit Split novo.
    event DefaultSplitUpdated(Split oldSplit, Split newSplit);

    /// @notice Emitido em {setProjectSplit}.
    /// @param projectId Projeto com override.
    /// @param newSplit Split aplicado.
    event ProjectSplitUpdated(uint256 indexed projectId, Split newSplit);

    /// @notice Emitido em {clearProjectSplit}.
    /// @param projectId Projeto cujo override foi removido.
    event ProjectSplitCleared(uint256 indexed projectId);

    /// @notice Emitido em {setAppRecipient}.
    /// @param projectId Projeto cujo recipient foi alterado.
    /// @param oldRecipient Valor anterior (pode ser `address(0)` = lookup dinamico).
    /// @param newRecipient Valor novo (pode ser `address(0)` = resetar para lookup).
    event AppRecipientUpdated(uint256 indexed projectId, address indexed oldRecipient, address indexed newRecipient);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    /// @notice Split informado nao soma 10_000 bps.
    /// @param burnBps Fatia de burn informada.
    /// @param treasuryBps Fatia de treasury informada.
    /// @param rebateBps Fatia de rebate informada.
    /// @param total Soma efetiva (`burnBps + treasuryBps + rebateBps`).
    error InvalidSplit(uint16 burnBps, uint16 treasuryBps, uint16 rebateBps, uint16 total);

    /// @notice Projeto nao esta em status Active (cobre Pending, Probation,
    ///         Removed e inexistente).
    /// @param projectId Projeto consultado.
    error ProjectNotActive(uint256 projectId);

    /// @notice Valor zero nao e permitido em operacoes que exigem > 0.
    error ZeroAmount();

    /// @notice Endereco zero nao e valido onde um endereco real e exigido.
    error ZeroAddress();

    /// @notice {setAppRecipient} chamado por alguem que nao e o owner do projeto.
    /// @param projectId Projeto em questao.
    /// @param caller Quem tentou chamar.
    error NotProjectOwner(uint256 projectId, address caller);

    /// @notice {clearProjectSplit} chamado em projeto sem override registrado.
    /// @param projectId Projeto em questao.
    error NoProjectSplit(uint256 projectId);

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    /**
     * @notice Cria o router apontando para dependencias e seta o split default.
     * @dev Concede `DEFAULT_ADMIN_ROLE` e `GOVERNANCE_ROLE` ao `admin`. Em
     *      producao o deploy script transfere ambas ao TimelockController e
     *      renuncia as roles do admin inicial (invariante I4). BURNER_ROLE no
     *      CreditToken nao e concedido aqui — o {BurnTracker} ja detem
     *      essa role, e o FeeRouter interage com CREDIT apenas via
     *      transfer/transferFrom/approve padroes.
     *      Validacoes:
     *       - `admin`, `credit`, `burnTracker`, `registry`, `treasury` != 0.
     *       - `initialDefaultSplit` soma exatamente 10_000 bps.
     *      RECORDER_ROLE no {BurnTracker} (exigida por {pay}) e concedida via
     *      proposta aprovada no Governor + Timelock, apos deploy.
     * @param admin Endereco que recebe admin e governance inicial.
     * @param credit Endereco do {CreditToken}.
     * @param burnTracker Endereco do {BurnTracker}.
     * @param registry Endereco do {ProjectRegistry}.
     * @param treasury Endereco do {Treasury}.
     * @param initialDefaultSplit Split global inicial (soma == 10_000).
     */
    constructor(
        address admin,
        address credit,
        address burnTracker,
        address registry,
        address treasury,
        Split memory initialDefaultSplit
    ) {
        if (
            admin == address(0) ||
            credit == address(0) ||
            burnTracker == address(0) ||
            registry == address(0) ||
            treasury == address(0)
        ) {
            revert ZeroAddress();
        }
        _requireValidSplit(initialDefaultSplit);

        CREDIT = CreditToken(credit);
        BURN_TRACKER = BurnTracker(burnTracker);
        REGISTRY = ProjectRegistry(registry);
        TREASURY = Treasury(payable(treasury));

        defaultSplit = initialDefaultSplit;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(GOVERNANCE_ROLE, admin);
    }

    // ------------------------------------------------------------------
    // Core — pay
    // ------------------------------------------------------------------

    /**
     * @notice Processa um pagamento de `user` no `projectId`, pullando
     *         `amount` de CREDIT via `transferFrom` e dividindo-o conforme
     *         o split efetivo (override do projeto, se existir; caso contrario,
     *         {defaultSplit}).
     * @dev Chamada publica: qualquer endereco pode iniciar, desde que `user`
     *      tenha aprovado ao FeeRouter pelo menos `amount` de CREDIT. O
     *      payer economico e sempre `user`; `msg.sender` so e registrado no
     *      evento {Paid.payer}.
     *      Pipeline (Checks → Effects → Interactions):
     *        1. Checks:
     *           - `user != 0`; `amount > 0`.
     *           - `REGISTRY.isActive(projectId)`.
     *        2. Interactions (entradas):
     *           - `transferFrom(user, this, amount)` — FeeRouter recebe o total.
     *        3. Calcula split (override ou default) e aloca `burned`,
     *           `toTreasury`, `toApp`. O residuo (`amount - burned -
     *           toTreasury`) vai integralmente para `toApp` (dust handling).
     *        4. Interactions (distribuicoes):
     *           - `transfer(recipient, toApp)` se `toApp > 0`.
     *           - `transfer(treasury, toTreasury)` se `toTreasury > 0`.
     *           - `approve(burnTracker, burned)` + `burnAndRecord(projectId,
     *             this, burned)` se `burned > 0` — o BurnTracker chama
     *             `CreditToken.burnByRole` que `_burn`a do FeeRouter.
     *      Reentrancy: modifier `nonReentrant` ativo durante todo o fluxo.
     *      Mesmo que um ERC-20 customizado com callback tentasse reentrar
     *      via `transfer` ou `approve`, o guard reverteria. `BurnTracker`
     *      tem seu proprio `nonReentrant`, cross-contract seguro.
     *      Gas: tipico ~180-220k para o caminho 95/0/5 (uma `transferFrom`,
     *      uma `transfer`, uma `approve`, uma chamada ao tracker que faz
     *      `_burn`). Splits que incluem treasury adicionam ~35k.
     * @param projectId Projeto ao qual o pagamento e atribuido. Deve estar Active.
     * @param user Endereco pagador economico. Deve ter aprovado o FeeRouter
     *             em pelo menos `amount` de CREDIT.
     * @param amount Valor a pagar (em wei de CREDIT). Deve ser > 0.
     * @return burned Fatia queimada via BurnTracker.
     * @return toTreasury Fatia transferida ao Treasury.
     * @return toApp Fatia transferida ao `appRecipient` efetivo.
     */
    function pay(
        uint256 projectId,
        address user,
        uint256 amount
    ) external nonReentrant returns (uint256 burned, uint256 toTreasury, uint256 toApp) {
        if (user == address(0)) {
            revert ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (!REGISTRY.isActive(projectId)) {
            revert ProjectNotActive(projectId);
        }

        Split memory split = _effectiveSplit(projectId);
        address recipient = _effectiveRecipient(projectId);

        burned = (amount * split.burnBps) / _BPS_DENOMINATOR;
        toTreasury = (amount * split.treasuryBps) / _BPS_DENOMINATOR;
        // Dust handling: residuo do truncamento vai para o rebate.
        toApp = amount - burned - toTreasury;

        // Entrada: puxa o valor total do user. Usa SafeERC20 mesmo com CREDIT
        // conhecido — padronizacao com o resto do codebase e tolerancia a
        // eventuais tokens-wrappers futuros.
        IERC20(address(CREDIT)).safeTransferFrom(user, address(this), amount);

        if (toApp > 0) {
            IERC20(address(CREDIT)).safeTransfer(recipient, toApp);
        }
        if (toTreasury > 0) {
            IERC20(address(CREDIT)).safeTransfer(address(TREASURY), toTreasury);
        }
        if (burned > 0) {
            // `forceApprove` garante allowance exata mesmo se algum allowance
            // residual de uma chamada anterior tivesse sobrado (nao deveria,
            // mas e barato e correto).
            IERC20(address(CREDIT)).forceApprove(address(BURN_TRACKER), burned);
            BURN_TRACKER.burnAndRecord(projectId, address(this), burned);
        }

        emit Paid(projectId, user, msg.sender, amount, burned, toTreasury, toApp, recipient);
    }

    // ------------------------------------------------------------------
    // Governance-gated setters
    // ------------------------------------------------------------------

    /**
     * @notice Atualiza o split global default.
     * @dev Restrito a {GOVERNANCE_ROLE}. Reverte com {InvalidSplit} se a soma
     *      nao for exatamente 10_000 bps. A alteracao afeta somente pagamentos
     *      futuros de projetos sem override — overrides existentes permanecem
     *      inalterados.
     * @param newSplit Novo split (`burnBps + treasuryBps + rebateBps == 10_000`).
     */
    function setDefaultSplit(Split calldata newSplit) external onlyRole(GOVERNANCE_ROLE) {
        _requireValidSplit(newSplit);
        Split memory old = defaultSplit;
        defaultSplit = newSplit;
        emit DefaultSplitUpdated(old, newSplit);
    }

    /**
     * @notice Registra/atualiza override de split para `projectId`.
     * @dev Restrito a {GOVERNANCE_ROLE}. Ativa {hasProjectSplit[projectId]} e
     *      passa a aplicar o override em {pay} e {getEffectiveSplit}. Pode ser
     *      chamada em qualquer projectId (ativa ou nao) — o override so surte
     *      efeito quando o projeto estiver Active no momento de {pay}.
     * @param projectId Projeto alvo.
     * @param newSplit Split a aplicar (soma == 10_000).
     */
    function setProjectSplit(uint256 projectId, Split calldata newSplit) external onlyRole(GOVERNANCE_ROLE) {
        _requireValidSplit(newSplit);
        projectSplit[projectId] = newSplit;
        hasProjectSplit[projectId] = true;
        emit ProjectSplitUpdated(projectId, newSplit);
    }

    /**
     * @notice Remove o override de `projectId`, retomando o uso de {defaultSplit}.
     * @dev Restrito a {GOVERNANCE_ROLE}. Reverte com {NoProjectSplit} se nao
     *      houver override (idempotencia explicita — evita emitir evento
     *      espurio).
     * @param projectId Projeto alvo.
     */
    function clearProjectSplit(uint256 projectId) external onlyRole(GOVERNANCE_ROLE) {
        if (!hasProjectSplit[projectId]) {
            revert NoProjectSplit(projectId);
        }
        delete projectSplit[projectId];
        delete hasProjectSplit[projectId];
        emit ProjectSplitCleared(projectId);
    }

    // ------------------------------------------------------------------
    // Owner-gated setter
    // ------------------------------------------------------------------

    /**
     * @notice Registra/atualiza o endereco que recebe a fatia de rebate de
     *         `projectId`. Apenas o owner atual do projeto pode chamar.
     * @dev O owner e lido ao vivo do {ProjectRegistry.getProject} —
     *      `Registry.getProject` reverte com `ProjectNotFound` se o projectId
     *      nao existir, bubbling up naturalmente (nao precisamos replicar
     *      o erro aqui).
     *      Passar `address(0)` reseta para lookup dinamico: {pay} passara a
     *      ler `Registry.getProject(projectId).owner` a cada chamada,
     *      acompanhando transferencias de ownership automaticamente.
     *      Nao valida status do projeto — permite configurar recipient
     *      para um projeto Pending/Probation/Removed sem surpresas (as
     *      chamadas de {pay} ja bloqueiam status invalido independentemente).
     * @param projectId Projeto alvo.
     * @param recipient Novo recipient explicito, ou `address(0)` para voltar
     *                  ao lookup dinamico.
     */
    function setAppRecipient(uint256 projectId, address recipient) external {
        ProjectRegistry.Project memory p = REGISTRY.getProject(projectId);
        if (p.owner != msg.sender) {
            revert NotProjectOwner(projectId, msg.sender);
        }
        address old = appRecipient[projectId];
        appRecipient[projectId] = recipient;
        emit AppRecipientUpdated(projectId, old, recipient);
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------

    /**
     * @notice Retorna o split que seria aplicado a um {pay} em `projectId`
     *         com a configuracao atual.
     * @dev Override tem precedencia sobre {defaultSplit}.
     */
    function getEffectiveSplit(uint256 projectId) external view returns (Split memory) {
        return _effectiveSplit(projectId);
    }

    /**
     * @notice Retorna o endereco que receberia a fatia de rebate em um {pay}
     *         em `projectId` agora.
     * @dev Se {appRecipient}[projectId] estiver setado (!= 0), retorna esse
     *      valor. Caso contrario retorna `Registry.getProject(projectId).owner`
     *      (lookup dinamico). Reverte se o projeto nao existir (bubbles up
     *      de {Registry.getProject}).
     */
    function getEffectiveRecipient(uint256 projectId) external view returns (address) {
        return _effectiveRecipient(projectId);
    }

    /**
     * @notice Calcula (sem side effects) as 3 fatias de um pagamento de
     *         `amount` no `projectId`, usando o split efetivo corrente.
     * @dev Reverte com {ZeroAmount} se `amount == 0` — espelha a validacao
     *      do {pay} para que o caller nao se engane com "preview zero".
     *      NAO valida status do projeto: permite consultas even para projetos
     *      Pending/Probation/Removed (util para UI mostrar o split esperado
     *      antes de listar).
     */
    function quote(
        uint256 projectId,
        uint256 amount
    ) external view returns (uint256 burned, uint256 toTreasury, uint256 toApp) {
        if (amount == 0) {
            revert ZeroAmount();
        }
        Split memory split = _effectiveSplit(projectId);
        burned = (amount * split.burnBps) / _BPS_DENOMINATOR;
        toTreasury = (amount * split.treasuryBps) / _BPS_DENOMINATOR;
        toApp = amount - burned - toTreasury;
    }

    // ------------------------------------------------------------------
    // Internal helpers
    // ------------------------------------------------------------------

    /**
     * @dev Resolve o split efetivo: override por projeto ou default.
     */
    function _effectiveSplit(uint256 projectId) private view returns (Split memory) {
        if (hasProjectSplit[projectId]) {
            return projectSplit[projectId];
        }
        return defaultSplit;
    }

    /**
     * @dev Resolve o recipient efetivo: override por projeto ou owner do
     *      Registry (lookup dinamico).
     */
    function _effectiveRecipient(uint256 projectId) private view returns (address) {
        address explicitRecipient = appRecipient[projectId];
        if (explicitRecipient != address(0)) {
            return explicitRecipient;
        }
        return REGISTRY.getProject(projectId).owner;
    }

    /**
     * @dev Valida que a soma dos 3 bps e exatamente 10_000. Reverte
     *      com {InvalidSplit} caso contrario.
     */
    function _requireValidSplit(Split memory split) private pure {
        // Soma em uint32 para evitar qualquer risco de overflow do uint16
        // (cada campo sozinho ja cabe em 10_000, mas a soma pode chegar a
        // 30_000 se os 3 forem maximos — ainda cabe em uint16, mas uint32
        // e defensivo e gera codigo mais claro para o static analyzer).
        uint32 total = uint32(split.burnBps) + uint32(split.treasuryBps) + uint32(split.rebateBps);
        if (total != _BPS_DENOMINATOR) {
            revert InvalidSplit(split.burnBps, split.treasuryBps, split.rebateBps, uint16(total));
        }
    }
}

contracts/GovernanceToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {ERC20Votes} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import {Nonces} from "@openzeppelin/contracts/utils/Nonces.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

/**
 * @title GovernanceToken (GOV)
 * @notice Token ERC-20 com voto on-chain (ERC-5805 via ERC20Votes) e supply cap imutável
 *         para a DAO Web3Community. Emissão controlada pelo owner, que em produção é o
 *         TimelockController (transferência em 2 passos via Ownable2Step).
 * @dev Invariantes atendidas nesta unidade:
 *      - I1: Supply total limitado ao {cap}, enforced em {_update}; mint acima reverte.
 *      - I5: Voto via snapshot (ERC20Votes), nunca `balanceOf` atual — previne flash loan
 *            attacks na votação.
 *      O contrato deliberadamente NÃO pré-minta supply no constructor: toda a distribuição
 *      (30/25/20/15/10) acontece via chamadas explícitas de {mint} pelo owner, permitindo
 *      que o deploy orquestre endereços de treasury, cofre de vesting, sale, etc. sem
 *      hardcode. Uma vez o cap atingido, novos mints são impossíveis.
 * @custom:security-contact security@web3community.example
 */
contract GovernanceToken is ERC20, ERC20Permit, ERC20Votes, Ownable2Step {
    /// @notice Supply máximo imutável em unidades mínimas (wei-equivalent, 1e18 precision).
    /// @dev Fixado em 100.000.000 * 10^18. Cabe em uint208 do ERC20Votes sem risco de overflow.
    // solhint-disable-next-line var-name-mixedcase
    uint256 public immutable CAP_SUPPLY;

    /// @notice Emitido em todo mint bem-sucedido, com uma tag livre para rastrear a distribuição.
    /// @param to Endereço que recebeu os tokens cunhados.
    /// @param amount Quantidade cunhada (em unidades mínimas).
    /// @param tag Rótulo off-chain para o bucket (ex.: "treasury", "team", "publicSale").
    event Minted(address indexed to, uint256 amount, string tag);

    /// @notice Tentativa de mint excederia o supply cap imutável.
    /// @param attemptedSupply Supply total que resultaria do mint solicitado.
    /// @param cap Supply cap atual (imutável).
    error CapExceeded(uint256 attemptedSupply, uint256 cap);

    /// @notice Endereço zero não é válido como destinatário.
    error ZeroAddress();

    /// @notice Valor zero não é permitido em operações que exigem amount > 0.
    error ZeroAmount();

    /**
     * @notice Cria o token de governança com cap fixo de 100M * 10^18.
     * @dev O domain separator do EIP-712 usa `name` + version "1" (ver {ERC20Permit}).
     *      `initialOwner` deve ser o deployer em testnet local e o TimelockController
     *      em testnet pública/mainnet (ver invariante I4).
     * @param name_ Nome ERC-20 legível (ex.: "Web3Community Governance").
     * @param symbol_ Símbolo ERC-20 curto (ex.: "GOV").
     * @param initialOwner Owner inicial com poder de cunhar até atingir o cap.
     */
    constructor(
        string memory name_,
        string memory symbol_,
        address initialOwner
    ) ERC20(name_, symbol_) ERC20Permit(name_) Ownable(initialOwner) {
        CAP_SUPPLY = 100_000_000 * 10 ** 18;
    }

    /**
     * @notice Retorna o supply cap imutável do token.
     * @return Cap em unidades mínimas (1e18 precision).
     */
    function cap() external view returns (uint256) {
        return CAP_SUPPLY;
    }

    /**
     * @notice Cunha `amount` tokens para `to`, desde que o cap não seja excedido.
     * @dev Apenas o owner atual pode chamar. Em produção o owner é o TimelockController,
     *      de modo que cada mint passa por proposta + votação + timelock. O parâmetro
     *      `tag` é só registro off-chain (via evento) e não afeta contabilidade on-chain.
     *      Reverte com {ZeroAddress} se `to == address(0)`, {ZeroAmount} se `amount == 0`
     *      e {CapExceeded} se a soma do supply ultrapassar {CAP_SUPPLY}.
     * @param to Destinatário dos tokens.
     * @param amount Quantidade a cunhar (em unidades mínimas).
     * @param tag Rótulo descritivo do bucket/propósito (apenas evento, opcional).
     */
    function mint(address to, uint256 amount, string calldata tag) external onlyOwner {
        if (to == address(0)) {
            revert ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        _mint(to, amount);
        emit Minted(to, amount, tag);
    }

    /**
     * @notice Retorna o nonce atual de `ownerAddr` usado em {permit} e {delegateBySig}.
     * @param ownerAddr Endereço a consultar.
     * @return Nonce corrente.
     */
    function nonces(address ownerAddr) public view override(ERC20Permit, Nonces) returns (uint256) {
        return super.nonces(ownerAddr);
    }

    // ------------------------------------------------------------------
    // Internal overrides exigidos pela combinação ERC20 + ERC20Votes.
    // ------------------------------------------------------------------

    /**
     * @dev Hook unificado de transferências/mints/burns do ERC-20. Delega para
     *      {ERC20Votes._update}, que move voting units e aplica a proteção
     *      {ERC20ExceededSafeSupply} (limite uint208). Antes de chamar super,
     *      aplicamos o cap específico do projeto para falhar com erro mais
     *      descritivo ({CapExceeded}) em mints acima do limite.
     */
    function _update(address from, address to, uint256 value) internal override(ERC20, ERC20Votes) {
        if (from == address(0)) {
            uint256 attempted = totalSupply() + value;
            if (attempted > CAP_SUPPLY) {
                revert CapExceeded(attempted, CAP_SUPPLY);
            }
        }
        super._update(from, to, value);
    }

    /**
     * @dev Restringe o supply máximo reconhecido pelo ERC20Votes ao cap do projeto,
     *      garantindo que qualquer caminho interno que consulte `_maxSupply` respeite
     *      a invariante I1. Em resolução de conflitos de override, o mínimo prevalece.
     */
    function _maxSupply() internal view override returns (uint256) {
        return CAP_SUPPLY;
    }
}

contracts/ProjectRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title ProjectRegistry
 * @notice Whitelist on-chain de projetos/apps do ecossistema Web3Community. Fonte
 *         unica da verdade para: quem e owner de cada projeto, quanto GOV foi
 *         lockado como colateral (skin in the game), qual o status do projeto
 *         (Pending -> Active -> Probation -> Removed) e qual a metadata off-chain
 *         (IPFS/Arweave URI). Consumido por `Staking`, `BurnTracker` e
 *         `RewardDistributor` nas fases seguintes.
 * @dev Invariantes atendidas nesta unidade:
 *      - I7: Projetos sao adicionados/alterados/removidos apenas pelo
 *        `TimelockController` (portador de `GOVERNANCE_ROLE` em producao).
 *        A unica excecao e {updateMetadata} e {transferProjectOwnership} /
 *        {acceptProjectOwnership} — owner-gated, nao governance.
 *      - Custodia de colateral: Registry detem exatamente a soma dos
 *        colaterais declarados em projetos nao-Removed. Remocao move o valor
 *        para o treasury (slash) ou para o owner (clean).
 *      Desenho deliberado de duas nocoes distintas de "probation":
 *       - Probation por TEMPO (view {isInProbation}): true enquanto
 *         `block.timestamp < probationEndsAt` e `status == Active`.
 *         Probation inicial automatica aplicada a todo projeto recem-ativado
 *         durante `probationDuration`; reduz o peso de rewards (enforcement
 *         fica no `RewardDistributor`).
 *       - Probation PUNITIVA (status `Probation` do enum): governanca move
 *         manualmente um projeto Active para Probation por ma conduta;
 *         {isInProbation} retorna false nesse caso (porque status != Active),
 *         e {isActive} tambem retorna false — o projeto fica temporariamente
 *         suspenso ate {reactivate}.
 *      Reentrancia: {registerProject} e {removeProject} movem ERC-20 via
 *      {SafeERC20}. Como o token e o proprio GOV (ERC20Votes conhecido, sem
 *      hooks de callback), `ReentrancyGuard` seria redundante — seguimos o
 *      padrao CEI estritamente (Checks -> Effects -> Interactions) em ambas
 *      as funcoes, e qualquer integracao futura com GOV que mude esse modelo
 *      exige nova auditoria deste contrato.
 *      Reentrancia adicional: {updateMetadata} e {transferProjectOwnership}
 *      nao movem tokens — nao aplicavel.
 *      v1: nao ha topup/withdraw parcial de colateral. Uma vez registrado,
 *      o colateral so pode ser liberado via {removeProject}. Se v2 precisar
 *      de topup dentro dos limites de status, basta adicionar funcoes novas
 *      sem quebrar layout.
 * @custom:security-contact security@web3community.example
 */
contract ProjectRegistry is AccessControl {
    using SafeERC20 for IERC20;

    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------

    /// @notice Estados possiveis de um projeto. Transicoes validas:
    ///         Pending -> Active;
    ///         Active -> Probation; Active -> Removed;
    ///         Probation -> Active; Probation -> Removed;
    ///         Removed e terminal.
    enum Status {
        Pending,
        Active,
        Probation,
        Removed
    }

    /// @notice Registro completo de um projeto.
    /// @param owner Endereco com direito de atualizar metadata e iniciar
    ///              transferencia de ownership.
    /// @param collateral Quantidade de GOV lockada no Registry (wei).
    /// @param status Estado atual na maquina de status.
    /// @param activatedAt Timestamp (segundos) da primeira ativacao; 0 enquanto
    ///                    Pending. Nao e atualizado em transicoes posteriores
    ///                    (Probation/Active) para manter o ancoramento original.
    /// @param probationEndsAt Timestamp em que a probation inicial por tempo
    ///                        termina. Calculado em {activateProject} como
    ///                        `activatedAt + probationDuration`.
    /// @param metadataURI URI off-chain (IPFS/Arweave) com o restante dos
    ///                    dados (nome, descricao, icone, contract addresses
    ///                    do app, etc).
    struct Project {
        address owner;
        uint256 collateral;
        Status status;
        uint64 activatedAt;
        uint64 probationEndsAt;
        string metadataURI;
    }

    // ------------------------------------------------------------------
    // Roles
    // ------------------------------------------------------------------

    /// @notice Role concedida ao `TimelockController` em producao. Unica role
    ///         capaz de registrar, ativar, colocar em probation punitiva,
    ///         reativar, remover projetos e ajustar parametros economicos.
    bytes32 public constant GOVERNANCE_ROLE = keccak256("GOVERNANCE_ROLE");

    // ------------------------------------------------------------------
    // Immutable / storage
    // ------------------------------------------------------------------

    /// @notice Token de governanca (GOV) usado como colateral.
    // solhint-disable-next-line var-name-mixedcase
    IERC20 public immutable GOV_TOKEN;

    /// @notice Colateral minimo exigido para registrar um novo projeto (wei).
    uint256 public minCollateral;

    /// @notice Duracao da probation inicial automatica aplicada a projetos
    ///         recem-ativados (segundos). Afeta apenas ativacoes futuras.
    uint64 public probationDuration;

    /// @dev Contador incremental — proximo ID a ser atribuido. Comeca em 1
    ///      para que o ID 0 seja sempre invalido (simplifica checks).
    uint256 private _nextProjectId;

    /// @dev Mapeamento projectId => registro.
    mapping(uint256 => Project) private _projects;

    /// @dev Mapeamento projectId => endereco pendente da transferencia de
    ///      ownership 2-step. address(0) = nenhuma transferencia em curso.
    mapping(uint256 => address) private _pendingOwners;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    /// @notice Emitido ao registrar um novo projeto (status Pending).
    /// @param projectId ID atribuido (sempre >= 1).
    /// @param owner Owner declarado na criacao.
    /// @param collateral Quantidade de GOV lockada.
    /// @param metadataURI URI off-chain.
    event ProjectRegistered(uint256 indexed projectId, address indexed owner, uint256 collateral, string metadataURI);

    /// @notice Emitido ao mover um projeto de Pending para Active.
    /// @param projectId ID do projeto.
    /// @param activatedAt Timestamp (seg) da ativacao.
    /// @param probationEndsAt Timestamp (seg) em que a probation inicial
    ///                        termina.
    event ProjectActivated(uint256 indexed projectId, uint64 activatedAt, uint64 probationEndsAt);

    /// @notice Emitido ao mover Active para Probation (punitiva).
    event ProjectProbation(uint256 indexed projectId);

    /// @notice Emitido ao mover Probation para Active.
    event ProjectReactivated(uint256 indexed projectId);

    /// @notice Emitido na remocao terminal.
    /// @param projectId ID removido.
    /// @param slashed `true` se o colateral foi enviado ao treasury;
    ///                `false` se foi devolvido ao owner.
    /// @param collateralReturned Quantidade movida para o destino (treasury
    ///                           se slashed, owner caso contrario).
    event ProjectRemoved(uint256 indexed projectId, bool slashed, uint256 collateralReturned);

    /// @notice Emitido em {updateMetadata}.
    event MetadataUpdated(uint256 indexed projectId, string newMetadataURI);

    /// @notice Emitido em {transferProjectOwnership}.
    event OwnershipTransferInitiated(
        uint256 indexed projectId,
        address indexed currentOwner,
        address indexed pendingOwnerAddr
    );

    /// @notice Emitido em {acceptProjectOwnership}.
    event OwnershipTransferAccepted(uint256 indexed projectId, address indexed previousOwner, address indexed newOwner);

    /// @notice Emitido em {setMinCollateral}.
    event MinCollateralUpdated(uint256 oldMin, uint256 newMin);

    /// @notice Emitido em {setProbationDuration}.
    event ProbationDurationUpdated(uint64 oldDuration, uint64 newDuration);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    /// @notice Endereco zero nao e valido.
    error ZeroAddress();

    /// @notice Valor zero nao e permitido em operacoes que exigem > 0.
    error ZeroAmount();

    /// @notice URI de metadata vazia nao e permitida.
    error EmptyMetadataURI();

    /// @notice Colateral declarado abaixo do minimo vigente.
    /// @param provided Quantidade enviada pelo chamador.
    /// @param required `minCollateral` atual.
    error InsufficientCollateral(uint256 provided, uint256 required);

    /// @notice Allowance insuficiente do owner para o Registry executar o
    ///         `transferFrom` de registerProject. Preferimos revert explicito
    ///         aqui para mensagem de auditoria mais clara do que o revert
    ///         generico do ERC-20.
    /// @param provided Allowance atual.
    /// @param required Quantidade necessaria.
    error InsufficientAllowance(uint256 provided, uint256 required);

    /// @notice Projeto com `projectId` nao existe.
    error ProjectNotFound(uint256 projectId);

    /// @notice Projeto ja esta em status Removed — operacao bloqueada.
    error ProjectAlreadyRemoved(uint256 projectId);

    /// @notice Status atual nao permite a transicao solicitada.
    /// @param projectId ID do projeto.
    /// @param current Status atual (enum).
    /// @param expected Status exigido para a operacao (enum).
    error InvalidStatus(uint256 projectId, Status current, Status expected);

    /// @notice Chamador nao e o owner do projeto.
    error NotProjectOwner(uint256 projectId, address caller);

    /// @notice Chamador nao e o pending owner registrado para o projeto.
    error NotPendingOwner(uint256 projectId, address caller);

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    /**
     * @notice Cria o registry apontando para o token de colateral e concede
     *         `DEFAULT_ADMIN_ROLE` + `GOVERNANCE_ROLE` ao `initialAdmin`.
     * @dev Em producao o `initialAdmin` deve transferir `GOVERNANCE_ROLE` para
     *      o `TimelockController` e renunciar a propria role apos a transicao
     *      (via `grantRole`/`renounceRole` no script de deploy da fase 5).
     *      Params iniciais sao imediatamente ajustaveis via
     *      {setMinCollateral} e {setProbationDuration}.
     * @param govToken_ Endereco do `GovernanceToken` (GOV). Revertido se 0.
     * @param initialAdmin Endereco que recebe ambas as roles. Revertido se 0.
     * @param initialMinCollateral Valor inicial de `minCollateral` (wei).
     * @param initialProbationDuration Duracao inicial da probation automatica
     *                                 (segundos).
     */
    constructor(
        address govToken_,
        address initialAdmin,
        uint256 initialMinCollateral,
        uint64 initialProbationDuration
    ) {
        if (govToken_ == address(0) || initialAdmin == address(0)) {
            revert ZeroAddress();
        }
        if (initialMinCollateral == 0 || initialProbationDuration == 0) {
            revert ZeroAmount();
        }

        GOV_TOKEN = IERC20(govToken_);
        minCollateral = initialMinCollateral;
        probationDuration = initialProbationDuration;
        _nextProjectId = 1;

        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(GOVERNANCE_ROLE, initialAdmin);
    }

    // ------------------------------------------------------------------
    // Public view — exposes immutable as function for ABI ergonomics
    // ------------------------------------------------------------------

    /// @notice Endereco do token de colateral (GOV).
    function govToken() external view returns (address) {
        return address(GOV_TOKEN);
    }

    /// @notice Total de projetos ja registrados (inclui Removed).
    function totalProjects() external view returns (uint256) {
        return _nextProjectId - 1;
    }

    /**
     * @notice Retorna a struct completa do projeto.
     * @dev Reverte com {ProjectNotFound} se `projectId` nao existe.
     * @param projectId ID do projeto.
     * @return Project armazenado.
     */
    function getProject(uint256 projectId) external view returns (Project memory) {
        _requireExists(projectId);
        return _projects[projectId];
    }

    /**
     * @notice `true` se o projeto esta em status `Active` (inclui janela de
     *         probation automatica).
     * @dev Retorna `false` para projetos inexistentes em vez de reverter —
     *      permite uso em callers (Staking/RewardDistributor) sem try/catch.
     */
    function isActive(uint256 projectId) external view returns (bool) {
        if (!_exists(projectId)) {
            return false;
        }
        return _projects[projectId].status == Status.Active;
    }

    /**
     * @notice `true` se o projeto esta dentro da probation INICIAL POR TEMPO.
     *         Probation punitiva (status `Probation` do enum) retorna `false`
     *         aqui — a semantica deste view e estritamente "recem-ativado,
     *         com peso de reward reduzido". Callers devem combinar com
     *         `getProject(id).status == Status.Probation` para punitiva.
     * @dev Nao reverte para projetos inexistentes (ver {isActive}).
     */
    function isInProbation(uint256 projectId) external view returns (bool) {
        if (!_exists(projectId)) {
            return false;
        }
        Project storage p = _projects[projectId];
        if (p.status != Status.Active) {
            return false;
        }
        return block.timestamp < p.probationEndsAt;
    }

    /**
     * @notice Endereco pendente numa transferencia de ownership 2-step.
     *         `address(0)` se nao ha transferencia em curso ou projeto
     *         nao existe.
     */
    function pendingOwner(uint256 projectId) external view returns (address) {
        return _pendingOwners[projectId];
    }

    // ------------------------------------------------------------------
    // Governance-gated state changes
    // ------------------------------------------------------------------

    /**
     * @notice Registra um novo projeto em status `Pending`. Puxa `collateralAmount`
     *         de GOV do `owner` via `transferFrom` (o `owner` precisa ter
     *         aprovado o Registry antes).
     * @dev Restrito a `GOVERNANCE_ROLE` (invariante I7). O Registry confirma
     *      explicitamente a allowance antes do `transferFrom` para falhar com
     *      {InsufficientAllowance} em vez da mensagem generica do ERC-20.
     *      CEI: todos os checks primeiro, entao updates de storage (inclui
     *      incremento do contador e gravacao do registro), e somente no final
     *      o `safeTransferFrom`. Como o token e o GOV — ERC20Votes conhecido
     *      sem callbacks ao destinatario — CEI e suficiente sem
     *      `ReentrancyGuard`.
     * @param owner Owner do projeto (detentor do colateral e do poder de
     *              atualizar metadata / iniciar transferencia).
     * @param metadataURI URI off-chain. Nao pode ser vazia.
     * @param collateralAmount Quantidade de GOV a lockar. Deve ser >=
     *                         `minCollateral`.
     * @return projectId ID atribuido ao novo projeto (>= 1).
     */
    function registerProject(
        address owner,
        string calldata metadataURI,
        uint256 collateralAmount
    ) external onlyRole(GOVERNANCE_ROLE) returns (uint256 projectId) {
        if (owner == address(0)) {
            revert ZeroAddress();
        }
        if (bytes(metadataURI).length == 0) {
            revert EmptyMetadataURI();
        }
        uint256 minCol = minCollateral;
        if (collateralAmount < minCol) {
            revert InsufficientCollateral(collateralAmount, minCol);
        }

        uint256 allowance = GOV_TOKEN.allowance(owner, address(this));
        if (allowance < collateralAmount) {
            revert InsufficientAllowance(allowance, collateralAmount);
        }

        projectId = _nextProjectId;
        unchecked {
            _nextProjectId = projectId + 1;
        }

        _projects[projectId] = Project({
            owner: owner,
            collateral: collateralAmount,
            status: Status.Pending,
            activatedAt: 0,
            probationEndsAt: 0,
            metadataURI: metadataURI
        });

        emit ProjectRegistered(projectId, owner, collateralAmount, metadataURI);

        // Interaction (after Effects): pull collateral.
        GOV_TOKEN.safeTransferFrom(owner, address(this), collateralAmount);
    }

    /**
     * @notice Ativa um projeto `Pending`, setando `activatedAt` = block.timestamp
     *         e `probationEndsAt` = activatedAt + `probationDuration`.
     * @dev Restrito a `GOVERNANCE_ROLE`. Reverte com {InvalidStatus} se o
     *      projeto nao esta em `Pending`.
     * @param projectId ID do projeto.
     */
    function activateProject(uint256 projectId) external onlyRole(GOVERNANCE_ROLE) {
        Project storage p = _requireProject(projectId);
        if (p.status != Status.Pending) {
            revert InvalidStatus(projectId, p.status, Status.Pending);
        }

        uint64 nowTs = uint64(block.timestamp);
        uint64 endsAt = nowTs + probationDuration;

        p.status = Status.Active;
        p.activatedAt = nowTs;
        p.probationEndsAt = endsAt;

        emit ProjectActivated(projectId, nowTs, endsAt);
    }

    /**
     * @notice Move um projeto `Active` para `Probation` (punitiva). Nao altera
     *         `activatedAt` nem `probationEndsAt` — mantem o ancoramento
     *         original para que, apos {reactivate}, a probation por tempo
     *         permaneca consistente se ainda estiver dentro da janela.
     * @dev Restrito a `GOVERNANCE_ROLE`.
     * @param projectId ID do projeto.
     */
    function setProbation(uint256 projectId) external onlyRole(GOVERNANCE_ROLE) {
        Project storage p = _requireProject(projectId);
        if (p.status != Status.Active) {
            revert InvalidStatus(projectId, p.status, Status.Active);
        }
        p.status = Status.Probation;
        emit ProjectProbation(projectId);
    }

    /**
     * @notice Reabilita um projeto em `Probation`, movendo de volta para
     *         `Active`.
     * @dev Restrito a `GOVERNANCE_ROLE`.
     * @param projectId ID do projeto.
     */
    function reactivate(uint256 projectId) external onlyRole(GOVERNANCE_ROLE) {
        Project storage p = _requireProject(projectId);
        if (p.status != Status.Probation) {
            revert InvalidStatus(projectId, p.status, Status.Probation);
        }
        p.status = Status.Active;
        emit ProjectReactivated(projectId);
    }

    /**
     * @notice Remove um projeto (terminal). Se `slash == true`, o colateral
     *         vai para `treasury`; caso contrario, e devolvido ao owner atual.
     * @dev Restrito a `GOVERNANCE_ROLE`. Pode ser chamado em qualquer status
     *      != `Removed` (inclusive `Pending`). CEI: marca como `Removed`,
     *      zera `collateral` na storage e so entao executa o transfer —
     *      mesmo padrao de {registerProject}.
     *      Revert com {ZeroAddress} apenas quando `slash == true` e
     *      `treasury == address(0)`. Para `slash == false`, o destino e o
     *      owner do projeto, que nunca e zero (validado na criacao).
     * @param projectId ID do projeto.
     * @param slash `true` para enviar o colateral ao treasury; `false` para
     *              devolver ao owner.
     * @param treasury Destino do colateral em caso de slash. Ignorado se
     *                 `slash == false`.
     */
    function removeProject(uint256 projectId, bool slash, address treasury) external onlyRole(GOVERNANCE_ROLE) {
        Project storage p = _requireProject(projectId);
        if (p.status == Status.Removed) {
            revert ProjectAlreadyRemoved(projectId);
        }
        if (slash && treasury == address(0)) {
            revert ZeroAddress();
        }

        uint256 amount = p.collateral;
        address destination = slash ? treasury : p.owner;

        // Effects
        p.status = Status.Removed;
        p.collateral = 0;
        // Cancela qualquer transferencia de ownership pendente.
        if (_pendingOwners[projectId] != address(0)) {
            delete _pendingOwners[projectId];
        }

        emit ProjectRemoved(projectId, slash, amount);

        // Interaction. `amount` e sempre > 0 porque {registerProject} exige
        // `collateralAmount >= minCollateral`, e `minCollateral` nunca pode
        // ser zero (validado em {setMinCollateral} e no constructor).
        GOV_TOKEN.safeTransfer(destination, amount);
    }

    /**
     * @notice Atualiza `minCollateral`. Afeta apenas registros futuros.
     * @dev Restrito a `GOVERNANCE_ROLE`. Reverte com {ZeroAmount} se
     *      `newMin == 0`.
     */
    function setMinCollateral(uint256 newMin) external onlyRole(GOVERNANCE_ROLE) {
        if (newMin == 0) {
            revert ZeroAmount();
        }
        uint256 old = minCollateral;
        minCollateral = newMin;
        emit MinCollateralUpdated(old, newMin);
    }

    /**
     * @notice Atualiza `probationDuration`. Afeta apenas projetos ativados
     *         apos a mudanca — `probationEndsAt` ja gravado em projetos
     *         existentes nao e alterado.
     * @dev Restrito a `GOVERNANCE_ROLE`. Reverte com {ZeroAmount} se
     *      `newDuration == 0`.
     */
    function setProbationDuration(uint64 newDuration) external onlyRole(GOVERNANCE_ROLE) {
        if (newDuration == 0) {
            revert ZeroAmount();
        }
        uint64 old = probationDuration;
        probationDuration = newDuration;
        emit ProbationDurationUpdated(old, newDuration);
    }

    // ------------------------------------------------------------------
    // Owner-gated state changes
    // ------------------------------------------------------------------

    /**
     * @notice Atualiza a `metadataURI` do projeto. Somente o owner atual pode
     *         chamar — permite que correcoes off-chain (mudanca de icone, de
     *         CID do IPFS, de contract addresses do app) nao precisem passar
     *         pelo ciclo de governanca.
     * @dev Reverte com {ProjectAlreadyRemoved} se status == Removed (a URI
     *      fica congelada apos remocao).
     */
    function updateMetadata(uint256 projectId, string calldata metadataURI) external {
        Project storage p = _requireProject(projectId);
        if (p.status == Status.Removed) {
            revert ProjectAlreadyRemoved(projectId);
        }
        if (p.owner != msg.sender) {
            revert NotProjectOwner(projectId, msg.sender);
        }
        if (bytes(metadataURI).length == 0) {
            revert EmptyMetadataURI();
        }
        p.metadataURI = metadataURI;
        emit MetadataUpdated(projectId, metadataURI);
    }

    /**
     * @notice Inicia uma transferencia 2-step de ownership. O `newOwner` so
     *         assume apos chamar {acceptProjectOwnership}.
     * @dev Motivacao: mesma de `Ownable2Step` (OZ). Evita transferencia para
     *      endereco errado/inalcancavel. Uma segunda chamada antes do accept
     *      simplesmente sobrescreve o pendente.
     */
    function transferProjectOwnership(uint256 projectId, address newOwner) external {
        Project storage p = _requireProject(projectId);
        if (p.status == Status.Removed) {
            revert ProjectAlreadyRemoved(projectId);
        }
        if (p.owner != msg.sender) {
            revert NotProjectOwner(projectId, msg.sender);
        }
        if (newOwner == address(0)) {
            revert ZeroAddress();
        }
        _pendingOwners[projectId] = newOwner;
        emit OwnershipTransferInitiated(projectId, msg.sender, newOwner);
    }

    /**
     * @notice Aceita a transferencia de ownership. Deve ser chamado pelo
     *         `pendingOwner` registrado para o projeto.
     */
    function acceptProjectOwnership(uint256 projectId) external {
        Project storage p = _requireProject(projectId);
        address pending = _pendingOwners[projectId];
        if (pending == address(0) || pending != msg.sender) {
            revert NotPendingOwner(projectId, msg.sender);
        }
        address previous = p.owner;
        p.owner = pending;
        delete _pendingOwners[projectId];
        emit OwnershipTransferAccepted(projectId, previous, pending);
    }

    // ------------------------------------------------------------------
    // Internal helpers
    // ------------------------------------------------------------------

    /// @dev `true` se `projectId` foi atribuido (>= 1 e < `_nextProjectId`).
    function _exists(uint256 projectId) private view returns (bool) {
        return projectId != 0 && projectId < _nextProjectId;
    }

    /// @dev Reverte com {ProjectNotFound} se `projectId` nao existe.
    function _requireExists(uint256 projectId) private view {
        if (!_exists(projectId)) {
            revert ProjectNotFound(projectId);
        }
    }

    /// @dev Combina {_requireExists} com retorno de storage pointer —
    ///      reduz gas e reuso de codigo em todas as funcoes state-changing.
    function _requireProject(uint256 projectId) private view returns (Project storage) {
        _requireExists(projectId);
        return _projects[projectId];
    }
}

contracts/RewardDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {CreditToken} from "./CreditToken.sol";
import {BurnTracker} from "./BurnTracker.sol";
import {ProjectRegistry} from "./ProjectRegistry.sol";
import {Staking} from "./Staking.sol";

/**
 * @title RewardDistributor
 * @notice Coracao do modelo economico da Web3Community. Calcula a emissao de
 *         CREDIT por rodada (fase 4.1) e cunha-a sob demanda para stakers via
 *         claim pull-based. Consome (1) burn historico do {BurnTracker},
 *         (2) snapshot de peso global/por-projeto do {Staking} e (3) status
 *         dos projetos no {ProjectRegistry}.
 * @dev Formula da emissao por rodada R:
 *        emissao_R = min( max(alpha * burn_{R-1}, floor(R)), capMax )
 *      - alpha (FP 1e18) e o fator aplicado ao burn da rodada anterior.
 *        Default 0.95e18 — levemente deflacionario, para que a soma dos
 *        burns acumulados sempre supere a soma das emissoes se o uso
 *        permanecer constante.
 *      - floor(R) e um schedule decrescente de 24 rodadas (constructor-set,
 *        imutavel) que serve como "safety-net" de bootstrap — garante
 *        emissao positiva enquanto o ecossistema ainda nao gera burn.
 *      - capMax e o teto duro governance-tunable (default 5M CREDIT).
 *      A emissao por PROJETO dentro da rodada e calculada **sob demanda**
 *      em `_calculateClaim` (nao e pre-computada em `finalizeRound`) para
 *      que o custo de gas escale com o numero de claims efetuados, nao com
 *      o numero total de projetos listados no Registry:
 *        - Se `burn_{R-1}` > 0: projectShare = emissao * burn_{R-1,P} / burn_{R-1}
 *        - Se `burn_{R-1}` == 0 (bootstrap): projectShare via global weight
 *          do Staking — projectShare = emissao * totalWeight_P / globalWeight
 *          no snapshot do bloco de finalizacao. Requer `Staking.getGlobalWeightAt`
 *          (trilho de checkpoint global, O(1) por update).
 *      Probation (inicial por tempo no Registry): projectShare e multiplicado
 *      por 1/4 (25%). Os 75% restantes **nao sao redistribuidos** — sao
 *      simplesmente nao-cunhados. Decisao deliberada: redistribuir exigiria
 *      iteracao ou contador de "projetos nao-probation", aumentando complexidade
 *      e gas. A semantica "queima os 75%" e um desincentivo cristalino contra
 *      projetos em probation e preserva o cap economico.
 *
 *      **Pull-based claim**: nao ha push automatico de rewards. Cada staker
 *      chama {claim} ou {claimMany} para cunhar seus CREDIT ganhos. Evita
 *      gas explosion em rodadas com milhares de stakers e delega o custo
 *      para quem se beneficia.
 *
 *      **Snapshot semantics**: {finalizeRound} registra `block.number` como
 *      `snapshotBlock` da rodada. Todas as consultas de peso no claim usam
 *      esse bloco (via `getWeightAt` / `getTotalWeightAt` / `getGlobalWeightAt`),
 *      replicando a protecao anti-flash-loan da governanca ERC20Votes para
 *      a dimensao de share-of-rewards.
 *
 *      Invariantes economicas cobertas:
 *       - I2: burn gera reward por _consumo_, nao por volume passivo. Sem
 *         burn na rodada anterior, so o floor sustenta emissao.
 *       - I3: cap por rodada (capMax, governance-tunable) + schedule
 *         decrescente (floor) garantem emissao limitada por design.
 *       - I5: snapshot historico do Staking (ERC20Votes-like) impede
 *         flash-stake na rodada para capturar rewards.
 *       - I6: lock minimo 14d no Staking torna flash-stake inviavel.
 *       - I7: projetos entram via Registry apenas com proposta aprovada;
 *         probation punitiva (status != Active) retorna share zero.
 * @custom:security-contact security@web3community.example
 */
contract RewardDistributor is AccessControl, ReentrancyGuard {
    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------

    /// @notice Snapshot imutavel de uma rodada apos {finalizeRound}.
    /// @param totalEmission Emissao total calculada (em CREDIT wei).
    /// @param totalBurnAtFinalize Burn total da rodada anterior (imutavel
    ///                            apos finalize, evita depender do mapping
    ///                            do tracker em queries posteriores).
    /// @param snapshotBlock Block.number no momento do finalize. Usado para
    ///                      todas as consultas de peso no claim.
    /// @param finalized `true` se a rodada ja passou pelo finalize.
    struct RoundData {
        uint256 totalEmission;
        uint256 totalBurnAtFinalize;
        uint64 snapshotBlock;
        bool finalized;
    }

    // ------------------------------------------------------------------
    // Constants
    // ------------------------------------------------------------------

    /// @notice Role concedida ao `TimelockController` em producao. Unica capaz
    ///         de ajustar {alpha} e {capMax}. {finalizeRound} e {claim} nao
    ///         sao role-gated (permission-less) — destravam sem governanca.
    bytes32 public constant GOVERNANCE_ROLE = keccak256("GOVERNANCE_ROLE");

    /// @notice Precisao FP dos parametros economicos (alpha).
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant PRECISION = 1e18;

    /// @notice Limite inferior de {alpha}. 0.5e18 = 0.5 — abaixo torna a
    ///         emissao dominantemente controlada pelo floor, perdendo o
    ///         acoplamento com o burn real.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MIN_ALPHA = 5e17;

    /// @notice Limite superior de {alpha}. 1.1e18 = 1.1 — acima provoca
    ///         inflacao tonal (emissao > burn), contrariando o modelo
    ///         levemente deflacionario.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MAX_ALPHA = 11e17;

    /// @notice Limite inferior de {capMax}. 1 CREDIT — impede cap zero
    ///         que zerava rewards sem aviso.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MIN_CAPMAX = 1e18;

    /// @notice Limite superior de {capMax}. 100M CREDIT — cap sanitario,
    ///         emissoes acima disso nunca fazem sentido economico.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MAX_CAPMAX = 100_000_000e18;

    /// @notice Tamanho do schedule de floor (genesis decay). 24 rodadas e
    ///         ~6 meses com `roundDuration = 7d`.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant FLOOR_SCHEDULE_LENGTH = 24;

    /// @notice Denominador do penalty de probation (25% = share / 4).
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant PROBATION_PENALTY_DENOM = 4;

    // ------------------------------------------------------------------
    // Immutable dependencies
    // ------------------------------------------------------------------

    /// @notice Token de credito cunhado aos stakers como reward.
    // solhint-disable-next-line var-name-mixedcase
    CreditToken public immutable CREDIT;

    /// @notice Contrato de staking (peso + snapshots).
    // solhint-disable-next-line var-name-mixedcase
    Staking public immutable STAKING;

    /// @notice BurnTracker consultado para burn historico por projeto/rodada.
    // solhint-disable-next-line var-name-mixedcase
    BurnTracker public immutable BURN_TRACKER;

    /// @notice Registry consultado para status do projeto (isActive / isInProbation).
    // solhint-disable-next-line var-name-mixedcase
    ProjectRegistry public immutable REGISTRY;

    // ------------------------------------------------------------------
    // Governance-tunable params
    // ------------------------------------------------------------------

    /// @notice Alpha (FP 1e18). Multiplicador aplicado ao burn da rodada
    ///         anterior. Default 0.95e18.
    uint256 public alpha;

    /// @notice Cap maximo por rodada (em CREDIT wei). Teto duro da emissao.
    uint256 public capMax;

    /// @notice Schedule imutavel de floor por rodada. `floorSchedule[R]` e
    ///         aplicado ao round R. Rodadas >= 24 nao tem floor.
    uint256[24] public floorSchedule;

    // ------------------------------------------------------------------
    // Round state
    // ------------------------------------------------------------------

    /// @notice Ultima rodada finalizada. Junto com {isFirstRoundFinalized}
    ///         controla a invariante de sequencialidade em {finalizeRound}.
    uint256 public lastFinalizedRound;

    /// @notice Flag one-shot que distingue "round 0 ja finalizado" de
    ///         "nenhum round finalizado ainda" — sem ela nao tem como
    ///         representar o estado inicial com `lastFinalizedRound == 0`.
    bool public isFirstRoundFinalized;

    /// @notice Snapshot imutavel por rodada apos finalize.
    mapping(uint256 round => RoundData) public roundData;

    /// @notice `true` se (user, round, projectId) ja executou {claim} com
    ///         amount > 0. Evita double-claim.
    mapping(uint256 round => mapping(uint256 projectId => mapping(address user => bool))) public claimed;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    /// @notice Emitido em {finalizeRound}. `totalEmission` e o valor da
    ///         formula (min(max(alpha*burn, floor), cap)).
    event RoundFinalized(
        uint256 indexed round,
        uint256 totalEmission,
        uint256 totalBurnAtFinalize,
        uint64 snapshotBlock
    );

    /// @notice Emitido a cada {claim} que cunhou CREDIT. `amount == 0` nao
    ///         emite — claim sem peso e no-op silencioso.
    event Claimed(address indexed user, uint256 indexed round, uint256 indexed projectId, uint256 amount);

    /// @notice Emitido em {setAlpha}.
    event AlphaUpdated(uint256 oldAlpha, uint256 newAlpha);

    /// @notice Emitido em {setCapMax}.
    event CapMaxUpdated(uint256 oldCap, uint256 newCap);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    /// @notice Endereco zero nao e valido.
    error ZeroAddress();

    /// @notice A rodada ainda nao foi fechada no `BurnTracker`.
    error RoundNotClosed(uint256 round);

    /// @notice A rodada ja foi finalizada — `roundData[round].finalized == true`.
    error RoundAlreadyFinalized(uint256 round);

    /// @notice A rodada nao foi finalizada — claim/preview exigem finalize.
    error RoundNotFinalized(uint256 round);

    /// @notice Tentativa de finalizar fora de ordem. Exigimos sequencialidade:
    ///         round 0, depois 1, depois 2, etc.
    error OutOfOrderFinalize(uint256 expected, uint256 provided);

    /// @notice Claim duplicado para (round, projectId, user).
    error AlreadyClaimed(uint256 round, uint256 projectId, address user);

    /// @notice claimMany recebeu arrays de tamanhos diferentes.
    error ArrayLengthMismatch();

    /// @notice claimMany recebeu arrays vazios.
    error EmptyBatch();

    /// @notice alpha fora dos bounds permitidos.
    error InvalidAlpha(uint256 provided, uint256 min, uint256 max);

    /// @notice capMax fora dos bounds permitidos.
    error InvalidCapMax(uint256 provided, uint256 min, uint256 max);

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    /**
     * @notice Cria o distributor amarrado aos contratos da fase 1-3 e
     *         recebe os parametros economicos iniciais.
     * @dev Valida todos os enderecos != 0, alpha em `[MIN_ALPHA, MAX_ALPHA]`,
     *      capMax em `[MIN_CAPMAX, MAX_CAPMAX]` e copia o floorSchedule para
     *      storage. O schedule tem tamanho fixo 24 — a assinatura usa
     *      `uint256[24]` para forcar o caller a passar os 24 valores (array
     *      dinamico exigiria check adicional de length).
     *      Concede `DEFAULT_ADMIN_ROLE` e `GOVERNANCE_ROLE` ao `admin`.
     *      Em producao o `admin` transfere `GOVERNANCE_ROLE` ao
     *      TimelockController e renuncia (invariante I4) via deploy script.
     * @param admin Endereco que recebe admin e governance inicial.
     * @param credit_ Endereco do `CreditToken`.
     * @param staking_ Endereco do `Staking`.
     * @param burnTracker_ Endereco do `BurnTracker`.
     * @param registry_ Endereco do `ProjectRegistry`.
     * @param initialAlpha Alpha inicial (FP 1e18, em `[MIN_ALPHA, MAX_ALPHA]`).
     * @param initialCapMax Cap inicial (CREDIT wei, em `[MIN_CAPMAX, MAX_CAPMAX]`).
     * @param initialFloorSchedule Array fixo de 24 valores (floor por rodada).
     */
    constructor(
        address admin,
        address credit_,
        address staking_,
        address burnTracker_,
        address registry_,
        uint256 initialAlpha,
        uint256 initialCapMax,
        uint256[24] memory initialFloorSchedule
    ) {
        if (
            admin == address(0) ||
            credit_ == address(0) ||
            staking_ == address(0) ||
            burnTracker_ == address(0) ||
            registry_ == address(0)
        ) {
            revert ZeroAddress();
        }
        if (initialAlpha < MIN_ALPHA || initialAlpha > MAX_ALPHA) {
            revert InvalidAlpha(initialAlpha, MIN_ALPHA, MAX_ALPHA);
        }
        if (initialCapMax < MIN_CAPMAX || initialCapMax > MAX_CAPMAX) {
            revert InvalidCapMax(initialCapMax, MIN_CAPMAX, MAX_CAPMAX);
        }

        CREDIT = CreditToken(credit_);
        STAKING = Staking(staking_);
        BURN_TRACKER = BurnTracker(burnTracker_);
        REGISTRY = ProjectRegistry(registry_);

        alpha = initialAlpha;
        capMax = initialCapMax;
        for (uint256 i = 0; i < FLOOR_SCHEDULE_LENGTH; i++) {
            floorSchedule[i] = initialFloorSchedule[i];
        }

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(GOVERNANCE_ROLE, admin);
    }

    // ------------------------------------------------------------------
    // Core — state-changing
    // ------------------------------------------------------------------

    /**
     * @notice Finaliza a rodada `round`, calculando e gravando
     *         `roundData[round]`. Permissionless — qualquer um pode destravar
     *         claims apos o `closeRound` do `BurnTracker`.
     * @dev Ordem de checks:
     *       - round deve ser sequencial: `round == lastFinalizedRound + 1`
     *         (ou `round == 0` se `!isFirstRoundFinalized`).
     *       - `BurnTracker.currentRound() > round` — a rodada precisa ter
     *         sido fechada no tracker.
     *       - `!roundData[round].finalized` — nao refaz.
     *      Formula: emissao = min(max(alpha * burn_{R-1}, floor(R)), capMax).
     *      Para round 0 nao ha rodada anterior — `burn_{R-1}` e considerado
     *      0 (apenas o floor[0] define a emissao).
     *      Grava `snapshotBlock = block.number` para servir de ancora as
     *      consultas de peso no claim.
     *      Emite {RoundFinalized}.
     * @param round Rodada a finalizar.
     */
    function finalizeRound(uint256 round) external {
        // Checks. Ordem intencional: verificar "ja finalizado" antes de
        // "sequencial" para que a mensagem de erro em reentries seja
        // especifica (RoundAlreadyFinalized), nao o generico de ordem.
        if (roundData[round].finalized) {
            revert RoundAlreadyFinalized(round);
        }
        uint256 expected = isFirstRoundFinalized ? lastFinalizedRound + 1 : 0;
        if (round != expected) {
            revert OutOfOrderFinalize(expected, round);
        }
        if (BURN_TRACKER.currentRound() <= round) {
            revert RoundNotClosed(round);
        }

        // Computa burn da rodada anterior (0 no caso de round 0).
        uint256 totalBurnPrev = round == 0 ? 0 : BURN_TRACKER.getTotalBurnForRound(round - 1);

        // Formula emissao.
        uint256 alphaBurn = (totalBurnPrev * alpha) / PRECISION;
        uint256 floorAmount = round < FLOOR_SCHEDULE_LENGTH ? floorSchedule[round] : 0;
        uint256 rawEmission = alphaBurn > floorAmount ? alphaBurn : floorAmount;
        uint256 totalEmission = rawEmission > capMax ? capMax : rawEmission;

        // Effects.
        uint64 snapshotBlock = uint64(block.number);
        roundData[round] = RoundData({
            totalEmission: totalEmission,
            totalBurnAtFinalize: totalBurnPrev,
            snapshotBlock: snapshotBlock,
            finalized: true
        });
        lastFinalizedRound = round;
        isFirstRoundFinalized = true;

        emit RoundFinalized(round, totalEmission, totalBurnPrev, snapshotBlock);
    }

    /**
     * @notice Reivindica a parcela de rewards do `msg.sender` para
     *         (round, projectId). Calcula o valor sob demanda, marca
     *         `claimed[round][projectId][msg.sender] = true` e cunha
     *         CREDIT para o caller.
     * @dev Checks:
     *        - `roundData[round].finalized` (senao {RoundNotFinalized}).
     *        - `!claimed[round][projectId][msg.sender]` (senao {AlreadyClaimed}).
     *      Effects: marca claimed, emite {Claimed}.
     *      Interaction: `CREDIT.mint(msg.sender, amount, "rewardRound:<R>")`.
     *      Se `amount == 0` apos o calculo, nao marca claimed e nao cunha —
     *      deixa o usuario tentar de novo caso o estado mude (improvavel, mas
     *      evita "queimar" um slot de claim por erro).
     *      `nonReentrant` aplicado como defesa-em-profundidade (CREDIT.mint
     *      nao tem callback, mas blinda regressoes).
     * @param round Rodada.
     * @param projectId Projeto.
     * @return amount CREDIT cunhado.
     */
    function claim(uint256 round, uint256 projectId) external nonReentrant returns (uint256 amount) {
        amount = _claim(msg.sender, round, projectId);
    }

    /**
     * @notice Batch de claims por (round, projectId) para o `msg.sender`.
     *         Arrays paralelos.
     * @dev Reverte com {ArrayLengthMismatch} se lengths diferem e
     *      {EmptyBatch} se ambas vazias. Para cada par aplica a mesma
     *      logica de {claim} — entries com `amount == 0` sao ignoradas
     *      silenciosamente (nao marca claimed, nao revert). Entries ja
     *      claimadas revertem com {AlreadyClaimed}.
     * @param rounds Array de rodadas.
     * @param projectIds Array de projetos (mesmo tamanho).
     * @return total Soma dos amounts cunhados.
     */
    function claimMany(
        uint256[] calldata rounds,
        uint256[] calldata projectIds
    ) external nonReentrant returns (uint256 total) {
        uint256 n = rounds.length;
        if (n != projectIds.length) {
            revert ArrayLengthMismatch();
        }
        if (n == 0) {
            revert EmptyBatch();
        }
        for (uint256 i = 0; i < n; i++) {
            total += _claim(msg.sender, rounds[i], projectIds[i]);
        }
    }

    /**
     * @notice Atualiza {alpha}. Restrito a `GOVERNANCE_ROLE`.
     * @dev Reverte com {InvalidAlpha} se fora de `[MIN_ALPHA, MAX_ALPHA]`.
     *      A mudanca afeta APENAS rodadas ainda nao finalizadas — rodadas
     *      com `finalized == true` tem `totalEmission` imutavel.
     * @param newAlpha Novo alpha (FP 1e18).
     */
    function setAlpha(uint256 newAlpha) external onlyRole(GOVERNANCE_ROLE) {
        if (newAlpha < MIN_ALPHA || newAlpha > MAX_ALPHA) {
            revert InvalidAlpha(newAlpha, MIN_ALPHA, MAX_ALPHA);
        }
        uint256 old = alpha;
        alpha = newAlpha;
        emit AlphaUpdated(old, newAlpha);
    }

    /**
     * @notice Atualiza {capMax}. Restrito a `GOVERNANCE_ROLE`.
     * @dev Reverte com {InvalidCapMax} se fora de `[MIN_CAPMAX, MAX_CAPMAX]`.
     *      Mesma semantica de {setAlpha} (apenas rodadas nao finalizadas).
     * @param newCap Novo cap (CREDIT wei).
     */
    function setCapMax(uint256 newCap) external onlyRole(GOVERNANCE_ROLE) {
        if (newCap < MIN_CAPMAX || newCap > MAX_CAPMAX) {
            revert InvalidCapMax(newCap, MIN_CAPMAX, MAX_CAPMAX);
        }
        uint256 old = capMax;
        capMax = newCap;
        emit CapMaxUpdated(old, newCap);
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------

    /**
     * @notice Preview do amount claimavel por `user` em (round, projectId)
     *         sem side effects.
     * @dev Retorna 0 em qualquer caso de rejeicao (round nao finalizado,
     *      ja claimado, peso zero, projeto nao Active em bootstrap).
     *      Usa a mesma logica interna de {_claim}.
     * @param user Endereco do staker.
     * @param round Rodada.
     * @param projectId Projeto.
     * @return amount Valor que seria cunhado em um {claim} agora.
     */
    function previewClaim(address user, uint256 round, uint256 projectId) external view returns (uint256 amount) {
        if (!roundData[round].finalized) {
            return 0;
        }
        if (claimed[round][projectId][user]) {
            return 0;
        }
        return _calculateClaim(user, round, projectId);
    }

    /**
     * @notice Preview da emissao total para `forRound`, aplicando a formula
     *         atual sem gravar state.
     * @dev Para rounds finalizados, retorna `roundData[round].totalEmission`
     *      (imutavel). Para rounds nao finalizados com `forRound > 0`, le
     *      `totalBurnByRound[forRound - 1]` do tracker — se a rodada
     *      anterior ainda estiver aberta, o valor pode mudar ate o
     *      fechamento dela. Consumir com cuidado off-chain.
     * @param forRound Rodada a prever.
     * @return Emissao estimada.
     */
    function previewEmission(uint256 forRound) external view returns (uint256) {
        if (roundData[forRound].finalized) {
            return roundData[forRound].totalEmission;
        }
        uint256 totalBurnPrev = forRound == 0 ? 0 : BURN_TRACKER.getTotalBurnForRound(forRound - 1);
        uint256 alphaBurn = (totalBurnPrev * alpha) / PRECISION;
        uint256 floorAmount = forRound < FLOOR_SCHEDULE_LENGTH ? floorSchedule[forRound] : 0;
        uint256 rawEmission = alphaBurn > floorAmount ? alphaBurn : floorAmount;
        return rawEmission > capMax ? capMax : rawEmission;
    }

    /// @notice Emissao de uma rodada finalizada (0 se nao finalizada).
    function getEmission(uint256 round) external view returns (uint256) {
        return roundData[round].totalEmission;
    }

    /// @notice Share de emissao para (round, projectId) — util pra UI. 0 se
    ///         round nao finalizado.
    function getProjectEmission(uint256 round, uint256 projectId) external view returns (uint256) {
        if (!roundData[round].finalized) {
            return 0;
        }
        return _projectShare(round, projectId);
    }

    /// @notice `true` se `round` passou pelo {finalizeRound}.
    function isFinalized(uint256 round) external view returns (bool) {
        return roundData[round].finalized;
    }

    // ------------------------------------------------------------------
    // Internal
    // ------------------------------------------------------------------

    /**
     * @dev Corpo compartilhado de {claim}/{claimMany}. Retorna o amount
     *      cunhado (0 se no-op).
     */
    function _claim(address user, uint256 round, uint256 projectId) private returns (uint256) {
        if (!roundData[round].finalized) {
            revert RoundNotFinalized(round);
        }
        if (claimed[round][projectId][user]) {
            revert AlreadyClaimed(round, projectId, user);
        }

        uint256 amount = _calculateClaim(user, round, projectId);
        if (amount == 0) {
            return 0;
        }

        // Effects.
        claimed[round][projectId][user] = true;
        emit Claimed(user, round, projectId, amount);

        // Interaction — CREDIT.mint. burnByRole/mint do CREDIT usam ERC20
        // nativo sem callback; nao ha vetor de reentrancia real.
        CREDIT.mint(user, amount, "rewardRound");
        return amount;
    }

    /**
     * @dev Calcula o amount que `user` pode claim em (round, projectId).
     *      Retorna 0 se projeto nao tem peso no snapshot ou user nao tem
     *      peso no projeto. Nao reverte — no-op silencioso.
     *      Aplica probation penalty (share / 4) se o projeto esta em
     *      probation inicial por tempo no Registry no momento da chamada.
     *      NOTA sobre probation: `isInProbation` e avaliado no momento do
     *      claim (nao do finalize). Isso e intencional — probation e por
     *      tempo no Registry (`probationEndsAt`), so pode "terminar"
     *      naturalmente. Se probation terminou entre finalize e claim, o
     *      usuario recebe share cheio. Como probationEndsAt e setado no
     *      activate e nao muda, nao ha vetor de manipulacao.
     */
    function _calculateClaim(address user, uint256 round, uint256 projectId) private view returns (uint256) {
        uint256 share = _projectShare(round, projectId);
        if (share == 0) {
            return 0;
        }

        RoundData storage rd = roundData[round];
        uint256 snapBlock = rd.snapshotBlock;
        uint256 userWeight = STAKING.getWeightAt(user, projectId, snapBlock);
        if (userWeight == 0) {
            return 0;
        }
        // Invariante do Staking: projectWeight >= userWeight. Se userWeight > 0,
        // projectWeight > 0 obrigatoriamente (o projeto agrega o user).
        // Portanto a divisao e sempre segura, sem checagem redundante.
        uint256 projectWeight = STAKING.getTotalWeightAt(projectId, snapBlock);
        return (share * userWeight) / projectWeight;
    }

    /**
     * @dev Calcula o share do projeto na emissao total da rodada. Aplica
     *      probation penalty. Sem user-weight aqui.
     */
    function _projectShare(uint256 round, uint256 projectId) private view returns (uint256) {
        RoundData storage rd = roundData[round];
        uint256 totalEmission = rd.totalEmission;
        if (totalEmission == 0) {
            return 0;
        }
        uint256 snapBlock = rd.snapshotBlock;
        uint256 totalBurnPrev = rd.totalBurnAtFinalize;

        uint256 projectShare;
        if (totalBurnPrev > 0) {
            // Caminho com burn: share por burn proporcional.
            uint256 burnPrev = round == 0 ? 0 : BURN_TRACKER.getBurnForProjectInRound(round - 1, projectId);
            if (burnPrev == 0) {
                return 0;
            }
            projectShare = (totalEmission * burnPrev) / totalBurnPrev;
        } else {
            // Bootstrap: share via global weight do Staking.
            uint256 globalWeight = STAKING.getGlobalWeightAt(snapBlock);
            if (globalWeight == 0) {
                return 0;
            }
            uint256 projectWeight = STAKING.getTotalWeightAt(projectId, snapBlock);
            if (projectWeight == 0) {
                return 0;
            }
            projectShare = (totalEmission * projectWeight) / globalWeight;
        }

        // Probation penalty: share / 4.
        if (REGISTRY.isInProbation(projectId)) {
            projectShare = projectShare / PROBATION_PENALTY_DENOM;
        }
        return projectShare;
    }
}

contracts/Staking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Checkpoints} from "@openzeppelin/contracts/utils/structs/Checkpoints.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {ProjectRegistry} from "./ProjectRegistry.sol";

/**
 * @title Staking
 * @notice Cofre de stake direcionado por projeto. O usuario lockeia GOV em um
 *         `projectId` do {ProjectRegistry} e recebe `weight` proporcional ao
 *         amount e a duracao do lock. Peso alimenta o futuro `RewardDistributor`
 *         no calculo de share de rewards por projeto por rodada.
 * @dev Decisoes economicas fixadas (confirmadas com o user):
 *      - Lock minimo 14 dias, maximo 365 dias (multiplier satura em 4x acima).
 *      - Curva linear 1x (14d) -> 4x (365d). Valores fora do range: < 14d
 *        revertem com {LockTooShort}; > 365d NAO revertem (multiplier = 4x
 *        e o tempo real de lock e preservado).
 *      - Stake so e aceito em projetos `Active`. Probation/Removed bloqueiam
 *        stake novo, mas NUNCA bloqueiam unstake (usuario nao fica preso por
 *        decisao de governanca).
 *      - Projeto em `Removed` libera o stake imediatamente (bypass do lock):
 *        a DAO removeu o projeto, nao o staker; seria punitivo manter o lock.
 *      - Consolidacao em {stake} segue Opcao B: se ja existe posicao, o novo
 *        amount soma ao existente, o lockDuration passa a ser
 *        `max(remaining, newLockDuration)` e `lockStartAt` reseta para
 *        `block.timestamp`. Reset do start e intencional: sem ele, o usuario
 *        poderia alongar o peso indefinidamente fazendo micro-stakes sem
 *        re-commitar o amount antigo. Com o reset, qualquer acrescimo de
 *        amount re-inicia o compromisso temporal sobre TODA a posicao.
 *
 *      Invariantes atendidas nesta unidade:
 *      - I5 (anti-flashloan no voto): aqui nao ha voto, mas o analogo e a
 *        sensibilidade do peso a snapshots. Expomos {getWeightAt} e
 *        {getTotalWeightAt} via `Checkpoints.Trace208`. `RewardDistributor`
 *        deve consultar pelo blockNumber ancorado ao inicio da rodada, e
 *        NUNCA pelo valor corrente, impedindo que flash-staking no mesmo
 *        bloco da distribuicao influencie a fracao de reward alocada.
 *      - I6 (lock minimo 14d) — {LockTooShort} revert em {stake} e
 *        {extendLock}; {unstake} reverte com {LockNotExpired} enquanto o lock
 *        esta vigente (excecao de {unstake} documentada para status Removed).
 *      - Compat com {ProjectRegistry}: le `isActive` para gating de stake e
 *        le `getProject(projectId).status == Removed` para bypass de lock em
 *        unstake. Nenhuma role nova e necessaria — Staking nao e privilegiado
 *        na governanca.
 *
 *      Escolhas de implementacao:
 *      - `Checkpoints.Trace208` (chave uint48=block.number, valor uint208).
 *        Peso maximo teorico por (user, projeto): 100M * 1e18 * 4 = 4e26,
 *        cabe trivialmente em uint208 (~4.11e62). Chave cabe em uint48 por
 *        ~8920 anos em 1s block time. Documentado em {_pushCheckpoint}.
 *      - `ReentrancyGuard` em todas as 5 funcoes state-changing que tocam
 *        GOV. Mesmo sendo GOV um ERC20Votes conhecido sem callbacks, o guard
 *        e barato (~2k gas) e blinda contra regressao futura.
 *      - `SafeERC20` em todas as transferencias.
 *      - CEI estrito: effects antes de safeTransfer/safeTransferFrom.
 *      - Custom errors para todas as falhas. Eventos com `indexed` em
 *        `user` e `projectId` para indexacao off-chain.
 * @custom:security-contact security@web3community.example
 */
contract Staking is ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Checkpoints for Checkpoints.Trace208;
    using SafeCast for uint256;

    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------

    /// @notice Posicao de stake unica por par (user, projectId).
    /// @param amount GOV atualmente lockado nesta posicao (wei). `0` significa
    ///               posicao inexistente/deletada.
    /// @param lockStartAt Timestamp (seg) em que o lock atual comecou. Reset
    ///                    em {stake} ao consolidar; preservado em
    ///                    {increaseStake} e {extendLock}.
    /// @param lockDuration Duracao absoluta do lock (seg) a partir de
    ///                     `lockStartAt`. Pode exceder `MAX_LOCK` (o
    ///                     multiplier saturam; o tempo real de lock e
    ///                     respeitado em {unstake}).
    struct StakePosition {
        uint256 amount;
        uint64 lockStartAt;
        uint64 lockDuration;
    }

    // ------------------------------------------------------------------
    // Constants
    // ------------------------------------------------------------------

    /// @notice Duracao minima do lock (14 dias). Stake/extend abaixo revertem.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MIN_LOCK = 14 days;

    /// @notice Duracao apos a qual o multiplier satura em `MAX_MULTIPLIER`.
    ///         Locks acima ainda sao aceitos — apenas nao incrementam peso.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MAX_LOCK = 365 days;

    /// @notice Precisao fixa do multiplier. `1e18` = 1.0x.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MULTIPLIER_PRECISION = 1e18;

    /// @notice Multiplier maximo (4x) atingido em `MAX_LOCK`.
    // solhint-disable-next-line const-name-snakecase
    uint256 public constant MAX_MULTIPLIER = 4e18;

    // ------------------------------------------------------------------
    // Immutable / storage
    // ------------------------------------------------------------------

    /// @notice Token de governanca (GOV) travado como colateral de stake.
    // solhint-disable-next-line var-name-mixedcase
    IERC20 public immutable GOV_TOKEN;

    /// @notice Registry consultado para validar status de projeto (Active para
    ///         stake novo; Removed para bypass de lock em unstake).
    // solhint-disable-next-line var-name-mixedcase
    ProjectRegistry public immutable REGISTRY;

    /// @notice Posicao de stake por (user, projectId). `amount == 0` indica
    ///         posicao inexistente.
    mapping(address user => mapping(uint256 projectId => StakePosition)) public positions;

    /// @notice Soma agregada de `amount` por projeto.
    mapping(uint256 projectId => uint256) public totalStakedByProject;

    /// @notice Total global de GOV lockado (soma entre todos os projetos).
    uint256 public totalStaked;

    /// @dev Historico de peso total por projeto (chave = block.number).
    mapping(uint256 projectId => Checkpoints.Trace208) private _projectWeight;

    /// @dev Historico de peso por (user, projectId) (chave = block.number).
    mapping(address user => mapping(uint256 projectId => Checkpoints.Trace208)) private _userWeight;

    /// @dev Historico de peso global (soma de todos os projetos) (chave = block.number).
    ///      Alimenta o split bootstrap do `RewardDistributor` quando nao ha burn na
    ///      rodada anterior: share_projeto = projectWeight / globalWeight, evitando
    ///      iteracao sobre projetos on-chain.
    Checkpoints.Trace208 private _globalWeightCheckpoints;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    /// @notice Emitido ao abrir ou consolidar uma posicao via {stake}.
    /// @param user Staker.
    /// @param projectId Projeto destino.
    /// @param amount Quantidade adicionada nesta chamada (nao o total da posicao).
    /// @param lockDuration Nova `lockDuration` aplicada (resultado da
    ///                     consolidacao max(remaining, newLockDuration)).
    /// @param lockStartAt Timestamp (seg) do (re)start do lock.
    /// @param weight Peso total da posicao apos a consolidacao.
    event Staked(
        address indexed user,
        uint256 indexed projectId,
        uint256 amount,
        uint64 lockDuration,
        uint64 lockStartAt,
        uint256 weight
    );

    /// @notice Emitido em {increaseStake}.
    /// @param user Staker.
    /// @param projectId Projeto.
    /// @param amountAdded Quantidade adicionada.
    /// @param newAmount Amount total da posicao apos o acrescimo.
    /// @param newWeight Peso total apos o acrescimo (lockDuration inalterado).
    event StakeIncreased(
        address indexed user,
        uint256 indexed projectId,
        uint256 amountAdded,
        uint256 newAmount,
        uint256 newWeight
    );

    /// @notice Emitido em {extendLock}.
    /// @param user Staker.
    /// @param projectId Projeto.
    /// @param newLockDuration Nova `lockDuration` (sempre > anterior).
    /// @param newWeight Peso total recalculado.
    event LockExtended(address indexed user, uint256 indexed projectId, uint64 newLockDuration, uint256 newWeight);

    /// @notice Emitido em {unstake} e {unstakeAll}.
    /// @param user Staker.
    /// @param projectId Projeto.
    /// @param amount Quantidade removida.
    /// @param remaining Amount restante da posicao apos a remocao (0 = posicao deletada).
    /// @param newWeight Peso restante (0 se a posicao foi deletada).
    event Unstaked(
        address indexed user,
        uint256 indexed projectId,
        uint256 amount,
        uint256 remaining,
        uint256 newWeight
    );

    /// @notice Emitido quando o unstake acontece com lock ainda vigente porque
    ///         o projeto esta `Removed`. Complemento de {Unstaked} para
    ///         rastreabilidade off-chain de bypass de lock.
    /// @param user Staker.
    /// @param projectId Projeto (em status Removed no momento da chamada).
    /// @param amount Quantidade removida sob bypass.
    event EarlyUnstakeAllowed(address indexed user, uint256 indexed projectId, uint256 amount);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    /// @notice Endereco zero nao e valido como construtor/registry/token.
    error ZeroAddress();

    /// @notice Valor zero nao e permitido em operacoes que exigem amount > 0.
    error ZeroAmount();

    /// @notice Projeto nao esta em status `Active` — stake novo bloqueado.
    /// @param projectId ID do projeto.
    error ProjectNotActive(uint256 projectId);

    /// @notice `lockDuration` abaixo de {MIN_LOCK}.
    /// @param provided Duracao passada.
    /// @param minimum {MIN_LOCK}.
    error LockTooShort(uint64 provided, uint256 minimum);

    /// @notice Lock ainda nao expirou e o projeto nao esta `Removed`.
    /// @param unlockAt Timestamp em que o lock expira.
    /// @param nowTs Timestamp atual.
    error LockNotExpired(uint64 unlockAt, uint256 nowTs);

    /// @notice Tentativa de encurtar o lock via {extendLock}.
    /// @param current `lockDuration` atual.
    /// @param provided `lockDuration` solicitado.
    error CannotShortenLock(uint64 current, uint64 provided);

    /// @notice Posicao inexistente para o par (user, projectId) solicitado.
    error PositionNotFound(address user, uint256 projectId);

    /// @notice Tentativa de remover mais do que a posicao contem.
    /// @param requested Quantidade solicitada.
    /// @param available Amount atual da posicao.
    error InsufficientStake(uint256 requested, uint256 available);

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    /**
     * @notice Cria o cofre de staking apontando para o token GOV e o registry.
     * @dev Nenhuma role e concedida — o contrato nao tem superficie
     *      privilegiada. Toda funcao state-changing e gated por logica de
     *      negocio (ownership da posicao, status do projeto, expiracao do
     *      lock) e nao por `AccessControl`.
     *      Revertido se qualquer endereco e zero.
     * @param govToken_ Endereco do `GovernanceToken` (GOV).
     * @param registry_ Endereco do `ProjectRegistry`.
     */
    constructor(address govToken_, address registry_) {
        if (govToken_ == address(0) || registry_ == address(0)) {
            revert ZeroAddress();
        }
        GOV_TOKEN = IERC20(govToken_);
        REGISTRY = ProjectRegistry(registry_);
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------

    /**
     * @notice Retorna a posicao completa para o par (user, projectId).
     * @dev Retorna struct zerada se nao ha posicao — chamadores que queiram
     *      distinguir "existe vs nao existe" devem checar `amount > 0`.
     * @param user Staker.
     * @param projectId Projeto.
     * @return Posicao completa (pode ser zerada).
     */
    function getPosition(address user, uint256 projectId) external view returns (StakePosition memory) {
        return positions[user][projectId];
    }

    /**
     * @notice Peso atual do (user, projectId). Zero se posicao nao existe.
     * @param user Staker.
     * @param projectId Projeto.
     * @return weight Peso corrente (amount * multiplier(lockDuration)).
     */
    function getWeight(address user, uint256 projectId) external view returns (uint256) {
        StakePosition storage p = positions[user][projectId];
        if (p.amount == 0) {
            return 0;
        }
        return _weight(p.amount, p.lockDuration);
    }

    /**
     * @notice Peso total agregado no projeto.
     * @param projectId Projeto.
     * @return Soma dos pesos de todas as posicoes vivas no projeto.
     */
    function getTotalWeight(uint256 projectId) external view returns (uint256) {
        return _projectWeight[projectId].latest();
    }

    /**
     * @notice Peso historico do (user, projectId) no bloco `blockNumber`.
     * @dev Consulta `Checkpoints.Trace208.upperLookupRecent` — retorna o peso
     *      vigente no ultimo checkpoint com chave <= `blockNumber`. Usado pelo
     *      `RewardDistributor` para snapshots imunes a flash-stake.
     *      IMPORTANTE: so e confiavel para `blockNumber < block.number`; para
     *      o bloco corrente, o checkpoint pode ainda estar sendo escrito.
     * @param user Staker.
     * @param projectId Projeto.
     * @param blockNumber Bloco de referencia.
     * @return Peso no bloco consultado.
     */
    function getWeightAt(address user, uint256 projectId, uint256 blockNumber) external view returns (uint256) {
        return _userWeight[user][projectId].upperLookupRecent(_toUint48(blockNumber));
    }

    /**
     * @notice Peso total agregado historico do projeto em `blockNumber`.
     * @dev Mesmas premissas de {getWeightAt}.
     * @param projectId Projeto.
     * @param blockNumber Bloco de referencia.
     * @return Peso total no bloco consultado.
     */
    function getTotalWeightAt(uint256 projectId, uint256 blockNumber) external view returns (uint256) {
        return _projectWeight[projectId].upperLookupRecent(_toUint48(blockNumber));
    }

    /**
     * @notice Peso global agregado corrente — soma de {getTotalWeight} para
     *         todos os projetos.
     * @dev Consultado pelo `RewardDistributor` em rodadas bootstrap (sem burn
     *      anterior) para computar o share de cada projeto sem iterar
     *      on-chain: `share_projeto = getTotalWeightAt(projectId, b) /
     *      getGlobalWeightAt(b)`. O agregado e atualizado em O(1) em cada
     *      {_writeCheckpoints} e usa o mesmo `Checkpoints.Trace208` dos outros
     *      trilhos de peso (mesmas invariantes de overflow).
     * @return Peso global atual.
     */
    function getGlobalWeight() external view returns (uint256) {
        return _globalWeightCheckpoints.latest();
    }

    /**
     * @notice Peso global historico em `blockNumber`.
     * @dev Mesmas premissas de {getWeightAt}: confiavel para
     *      `blockNumber < block.number`. No bloco corrente o checkpoint pode
     *      ainda estar sendo escrito.
     * @param blockNumber Bloco de referencia.
     * @return Peso global no bloco consultado.
     */
    function getGlobalWeightAt(uint256 blockNumber) external view returns (uint256) {
        return _globalWeightCheckpoints.upperLookupRecent(_toUint48(blockNumber));
    }

    /**
     * @notice Timestamp em que o lock do (user, projectId) expira.
     * @dev Retorna 0 se a posicao nao existe.
     * @param user Staker.
     * @param projectId Projeto.
     * @return Timestamp (seg) de expiracao.
     */
    function getLockEnd(address user, uint256 projectId) external view returns (uint64) {
        StakePosition storage p = positions[user][projectId];
        if (p.amount == 0) {
            return 0;
        }
        return p.lockStartAt + p.lockDuration;
    }

    /**
     * @notice `true` se o lock ja expirou (ou nao ha posicao).
     * @dev NAO considera status `Removed` do projeto — bypass de lock em
     *      Removed e aplicado dentro de {unstake}. Este view e estritamente
     *      sobre a expiracao temporal.
     * @param user Staker.
     * @param projectId Projeto.
     * @return `true` se `block.timestamp >= lockStartAt + lockDuration`
     *         ou se a posicao nao existe; `false` caso contrario.
     */
    function isUnlocked(address user, uint256 projectId) external view returns (bool) {
        StakePosition storage p = positions[user][projectId];
        if (p.amount == 0) {
            return true;
        }
        return block.timestamp >= uint256(p.lockStartAt) + uint256(p.lockDuration);
    }

    /**
     * @notice Multiplier linear em [1e18, 4e18] para `lockDuration`.
     * @dev Reverte com {LockTooShort} se `lockDuration < MIN_LOCK`.
     *      Satura em `MAX_MULTIPLIER` para `lockDuration >= MAX_LOCK`.
     *      Em [MIN_LOCK, MAX_LOCK]:
     *        multiplier = 1e18 + (d - MIN_LOCK) * (4e18 - 1e18) / (MAX_LOCK - MIN_LOCK)
     *      Pure para permitir testes numericos e uso pela UI sem estado.
     * @param lockDuration Duracao do lock (seg).
     * @return Multiplier em precisao 1e18.
     */
    function multiplier(uint64 lockDuration) external pure returns (uint256) {
        return _multiplier(lockDuration);
    }

    // ------------------------------------------------------------------
    // Core — state-changing
    // ------------------------------------------------------------------

    /**
     * @notice Abre ou consolida uma posicao de stake no `projectId`.
     * @dev Semantica de consolidacao (Opcao B):
     *        - Se nao ha posicao: grava {amount, lockDuration, lockStartAt=now}.
     *        - Se ha posicao: newAmount = old.amount + amount;
     *                        newLockDuration = max(remainingOld, lockDuration);
     *                        lockStartAt = now (reset intencional — ver
     *                        NatSpec contract-level).
     *      Reverts:
     *        - {ZeroAmount} se `amount == 0`.
     *        - {LockTooShort} se `lockDuration < MIN_LOCK`.
     *        - {ProjectNotActive} se projeto nao esta `Active` (inclui
     *          inexistente, `Pending`, `Probation` punitiva e `Removed`).
     *      Locks acima de {MAX_LOCK} sao aceitos literalmente: o multiplier
     *      satura em 4x, mas o tempo real e respeitado na hora do unstake.
     *      CEI: effects antes do `safeTransferFrom`. `nonReentrant` aplicado.
     *      Emite {Staked}.
     * @param projectId Projeto destino (deve estar Active no Registry).
     * @param amount Quantidade de GOV a lockar (> 0).
     * @param lockDuration Duracao (seg) do lock (>= {MIN_LOCK}).
     */
    function stake(uint256 projectId, uint256 amount, uint64 lockDuration) external nonReentrant {
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (lockDuration < MIN_LOCK) {
            revert LockTooShort(lockDuration, MIN_LOCK);
        }
        if (!REGISTRY.isActive(projectId)) {
            revert ProjectNotActive(projectId);
        }

        StakePosition storage p = positions[msg.sender][projectId];

        uint64 nowTs = uint64(block.timestamp);
        uint256 newAmount = p.amount + amount;
        uint64 newLockDuration = lockDuration;
        if (p.amount != 0) {
            // Consolidacao: max(remainingOld, lockDuration). `remainingOld` e
            // calculado relativo a `p.lockStartAt + p.lockDuration - now`,
            // saturado em 0 se o lock ja expirou.
            uint64 unlockAt = p.lockStartAt + p.lockDuration;
            uint64 remaining = unlockAt > nowTs ? unlockAt - nowTs : 0;
            if (remaining > newLockDuration) {
                newLockDuration = remaining;
            }
        }

        p.amount = newAmount;
        p.lockDuration = newLockDuration;
        p.lockStartAt = nowTs;

        totalStakedByProject[projectId] += amount;
        totalStaked += amount;

        uint256 newWeight = _weight(newAmount, newLockDuration);
        _writeCheckpoints(msg.sender, projectId, newWeight);

        emit Staked(msg.sender, projectId, amount, newLockDuration, nowTs, newWeight);

        GOV_TOKEN.safeTransferFrom(msg.sender, address(this), amount);
    }

    /**
     * @notice Aumenta `amount` de uma posicao existente PRESERVANDO
     *         `lockStartAt` e `lockDuration`.
     * @dev Peso aumenta proporcionalmente ao amount (mesmo multiplier).
     *      **NAO reabre lock expirado** — se a posicao ja esta unlocked,
     *      `increaseStake` nao altera o tempo; o staker pode imediatamente
     *      chamar `unstake` sobre o novo total. Para re-committar
     *      temporalmente, use {stake} (consolidacao Opcao B com reset de
     *      `lockStartAt`).
     *      Reverts:
     *        - {ZeroAmount} se `amount == 0`.
     *        - {PositionNotFound} se nao ha posicao para `msg.sender` em
     *          `projectId`.
     *        - {ProjectNotActive} se projeto nao esta `Active` (staker
     *          deve aguardar reativacao ou migrar via {stake} em outro
     *          projeto Active).
     *      CEI: effects antes do `safeTransferFrom`. `nonReentrant` aplicado.
     *      Emite {StakeIncreased}.
     * @param projectId Projeto.
     * @param amount Quantidade a adicionar (> 0).
     */
    function increaseStake(uint256 projectId, uint256 amount) external nonReentrant {
        if (amount == 0) {
            revert ZeroAmount();
        }
        StakePosition storage p = positions[msg.sender][projectId];
        if (p.amount == 0) {
            revert PositionNotFound(msg.sender, projectId);
        }
        if (!REGISTRY.isActive(projectId)) {
            revert ProjectNotActive(projectId);
        }

        uint256 newAmount = p.amount + amount;
        p.amount = newAmount;

        totalStakedByProject[projectId] += amount;
        totalStaked += amount;

        uint256 newWeight = _weight(newAmount, p.lockDuration);
        _writeCheckpoints(msg.sender, projectId, newWeight);

        emit StakeIncreased(msg.sender, projectId, amount, newAmount, newWeight);

        GOV_TOKEN.safeTransferFrom(msg.sender, address(this), amount);
    }

    /**
     * @notice Estende a `lockDuration` de uma posicao existente. Nunca
     *         encurta. NAO altera `lockStartAt`.
     * @dev Mesmo o lock ja tendo expirado, `extendLock` funciona: re-ativa
     *      o lock com a nova duracao medida a partir do `lockStartAt`
     *      original (ou seja, `newUnlockAt = lockStartAt + newLockDuration`).
     *      Reverts:
     *        - {PositionNotFound} se nao ha posicao.
     *        - {CannotShortenLock} se `newLockDuration <= lockDuration`
     *          atual (inclusive igual — nao ha valor em re-escrever o mesmo).
     *      {LockTooShort} nao pode ocorrer aqui: a duracao atual ja e
     *      >= MIN_LOCK por invariante de {stake}, e so aceitamos valores
     *      estritamente maiores.
     *      CEI + nonReentrant. Nao move tokens — o guard e defensivo contra
     *      regressoes futuras que introduzam call externo.
     *      Emite {LockExtended}.
     * @param projectId Projeto.
     * @param newLockDuration Nova duracao absoluta desde `lockStartAt` (seg).
     *                        Deve ser > `lockDuration` atual.
     */
    function extendLock(uint256 projectId, uint64 newLockDuration) external nonReentrant {
        StakePosition storage p = positions[msg.sender][projectId];
        if (p.amount == 0) {
            revert PositionNotFound(msg.sender, projectId);
        }
        if (newLockDuration <= p.lockDuration) {
            revert CannotShortenLock(p.lockDuration, newLockDuration);
        }

        p.lockDuration = newLockDuration;
        uint256 newWeight = _weight(p.amount, newLockDuration);
        _writeCheckpoints(msg.sender, projectId, newWeight);

        emit LockExtended(msg.sender, projectId, newLockDuration, newWeight);
    }

    /**
     * @notice Remove `amount` de GOV de uma posicao. Se `amount` iguala o
     *         saldo da posicao, a posicao e deletada (storage zerado).
     * @dev Requisitos:
     *        - `amount > 0` e posicao existente.
     *        - `amount <= position.amount`.
     *        - Lock expirado OU projeto em status `Removed` (bypass).
     *      Probation (punitiva ou inicial por tempo) NAO bypassa o lock —
     *      apenas remocao terminal bypassa.
     *      Reverts:
     *        - {ZeroAmount} se `amount == 0`.
     *        - {PositionNotFound} se nao ha posicao.
     *        - {InsufficientStake} se `amount > position.amount`.
     *        - {LockNotExpired} se lock vigente E projeto nao e `Removed`.
     *      Se projeto esta `Removed`, emite {EarlyUnstakeAllowed} alem de
     *      {Unstaked}. CEI: storage zerado antes do `safeTransfer`.
     *      `nonReentrant` aplicado.
     *      Emite {Unstaked} (sempre) e {EarlyUnstakeAllowed} (se bypass).
     * @param projectId Projeto.
     * @param amount Quantidade a remover (> 0, <= position.amount).
     */
    function unstake(uint256 projectId, uint256 amount) external nonReentrant {
        _unstake(projectId, amount);
    }

    /**
     * @notice Atalho: remove o saldo total da posicao.
     * @dev Semanticamente identico a {unstake} chamado com
     *      `amount = positions[msg.sender][projectId].amount`.
     *      Reverts:
     *        - {PositionNotFound} se nao ha posicao.
     *        - {LockNotExpired} se lock vigente E projeto nao e `Removed`
     *          (via `_unstake`).
     *      Emite {Unstaked} e (se bypass) {EarlyUnstakeAllowed}.
     * @param projectId Projeto.
     */
    function unstakeAll(uint256 projectId) external nonReentrant {
        StakePosition storage p = positions[msg.sender][projectId];
        if (p.amount == 0) {
            revert PositionNotFound(msg.sender, projectId);
        }
        _unstake(projectId, p.amount);
    }

    // ------------------------------------------------------------------
    // Internal
    // ------------------------------------------------------------------

    /**
     * @dev Corpo compartilhado de {unstake}/{unstakeAll}. Nao usa `nonReentrant`
     *      por si — o guard e aplicado nas funcoes externas.
     */
    function _unstake(uint256 projectId, uint256 amount) private {
        if (amount == 0) {
            revert ZeroAmount();
        }
        StakePosition storage p = positions[msg.sender][projectId];
        if (p.amount == 0) {
            revert PositionNotFound(msg.sender, projectId);
        }
        if (amount > p.amount) {
            revert InsufficientStake(amount, p.amount);
        }

        bool projectRemoved = _isProjectRemoved(projectId);
        if (!projectRemoved) {
            uint64 unlockAt = p.lockStartAt + p.lockDuration;
            if (block.timestamp < unlockAt) {
                revert LockNotExpired(unlockAt, block.timestamp);
            }
        }

        uint256 remaining = p.amount - amount;
        uint256 newWeight;
        if (remaining == 0) {
            delete positions[msg.sender][projectId];
            newWeight = 0;
        } else {
            p.amount = remaining;
            newWeight = _weight(remaining, p.lockDuration);
        }

        totalStakedByProject[projectId] -= amount;
        totalStaked -= amount;
        _writeCheckpoints(msg.sender, projectId, newWeight);

        if (projectRemoved) {
            emit EarlyUnstakeAllowed(msg.sender, projectId, amount);
        }
        emit Unstaked(msg.sender, projectId, amount, remaining, newWeight);

        GOV_TOKEN.safeTransfer(msg.sender, amount);
    }

    /**
     * @dev Le o Registry e retorna `true` se o projeto esta em status
     *      `Removed`. Abstraido em helper para permitir teste isolado do
     *      caminho de bypass.
     */
    function _isProjectRemoved(uint256 projectId) private view returns (bool) {
        ProjectRegistry.Project memory proj = REGISTRY.getProject(projectId);
        return proj.status == ProjectRegistry.Status.Removed;
    }

    /**
     * @dev Calcula peso = amount * multiplier(duration) / MULTIPLIER_PRECISION.
     *      Sem overflow em uint256: amount <= GOV cap (100M * 1e18 = 1e26),
     *      multiplier <= 4e18, produto <= 4e44 — muito abaixo de 2^256.
     */
    function _weight(uint256 amount, uint64 duration) private pure returns (uint256) {
        return (amount * _multiplier(duration)) / MULTIPLIER_PRECISION;
    }

    /**
     * @dev Multiplier com saturacao em {MAX_MULTIPLIER} para `duration >=
     *      MAX_LOCK`, revert para `duration < MIN_LOCK`, e interpolacao
     *      linear em [MIN_LOCK, MAX_LOCK). A ordem
     *      `delta * (MAX_MULTIPLIER - MULTIPLIER_PRECISION)` antes da divisao
     *      preserva precisao e nao overflow (ambos em uint64/uint256 seguros:
     *      delta <= ~3.1e7 seg, fator <= 3e18, produto <= ~1e26).
     */
    function _multiplier(uint64 duration) private pure returns (uint256) {
        if (duration < MIN_LOCK) {
            revert LockTooShort(duration, MIN_LOCK);
        }
        if (duration >= MAX_LOCK) {
            return MAX_MULTIPLIER;
        }
        uint256 delta = uint256(duration) - MIN_LOCK;
        uint256 slope = MAX_MULTIPLIER - MULTIPLIER_PRECISION;
        return MULTIPLIER_PRECISION + (delta * slope) / (MAX_LOCK - MIN_LOCK);
    }

    /**
     * @dev Escreve checkpoint (user, projeto e global) com o peso corrente.
     *      Chave = `block.number` (uint48), valor = peso (uint208).
     *      O agregado por projeto e recomputado como
     *      `oldProjectWeight - oldUserWeight + newUserWeight` — isso evita
     *      iterar sobre N stakers. O global usa o mesmo diff
     *      (`newUserWeight - oldUserWeight`) aplicado sobre o total global,
     *      preservando a invariante `globalWeight == SUM(projectWeight)` em
     *      O(1) por escrita.
     *      O diff e derivado dos valores correntes ANTES deste push; apos
     *      o push, os 3 trilhos ficam consistentes.
     *      `upperLookupRecent` / `latest` retornam o valor atual antes do
     *      novo push por essa razao (chamamos antes de `push`).
     */
    function _writeCheckpoints(address user, uint256 projectId, uint256 newUserWeight) private {
        Checkpoints.Trace208 storage userT = _userWeight[user][projectId];
        Checkpoints.Trace208 storage projT = _projectWeight[projectId];

        uint256 oldUserWeight = userT.latest();
        uint256 oldProjectWeight = projT.latest();
        uint256 oldGlobalWeight = _globalWeightCheckpoints.latest();
        // Reconstruir total: subtrai peso anterior do user (0 se nao tinha),
        // soma novo peso do user. Nao pode underflow: oldProjectWeight >=
        // oldUserWeight por invariante (projeto agrega todos os usuarios);
        // oldGlobalWeight >= oldUserWeight por invariante (global agrega
        // todos os projetos, que por sua vez agregam todos os usuarios).
        uint256 newProjectWeight = oldProjectWeight - oldUserWeight + newUserWeight;
        uint256 newGlobalWeight = oldGlobalWeight - oldUserWeight + newUserWeight;

        uint48 key = _toUint48(block.number);
        userT.push(key, _toUint208(newUserWeight));
        projT.push(key, _toUint208(newProjectWeight));
        _globalWeightCheckpoints.push(key, _toUint208(newGlobalWeight));
    }

    /// @dev SafeCast local — usa a lib OZ pra revert explicito em overflow.
    function _toUint48(uint256 v) private pure returns (uint48) {
        return SafeCast.toUint48(v);
    }

    /// @dev SafeCast local — mesma logica, mas para o valor de peso.
    function _toUint208(uint256 v) private pure returns (uint208) {
        return SafeCast.toUint208(v);
    }
}

contracts/TeamVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

/**
 * @title TeamVesting
 * @notice Cofre de vesting linear com cliff para distribuir GOV a um unico
 *         beneficiario do time. Padrao de deploy: uma instancia por membro
 *         (ou grupo custodiado por multi-sig). Simplifica contabilidade
 *         off-chain e isola revogacao — se alguem sai, a DAO revoga APENAS
 *         aquela instancia, sem afetar os demais.
 * @dev Convencoes de vesting:
 *      - `start` = timestamp de inicio do vesting (normalmente TGE).
 *      - `cliff` = offset em segundos a partir de `start`. Antes de
 *        `start + cliff`, releasable == 0.
 *      - `duration` = duracao TOTAL em segundos (inclui o cliff). Depois
 *        de `start + duration`, releasable == alocacao total.
 *      - Entre `start + cliff` e `start + duration`, o vested cresce
 *        linearmente por (timestamp - start) / duration — ou seja, no
 *        exato momento do cliff o beneficiario recebe `cliff / duration`
 *        da alocacao de uma vez (padrao "hockey stick" da industria).
 *
 *      Exemplo da proposta de distribuicao do repo (cliff 12m + linear 36m):
 *        cliff    = 365 days
 *        duration = 4 * 365 days  (= cliff + 3 anos = 48 meses totais)
 *        No TGE+12m, libera 25% de uma vez; depois disso pinga linearmente
 *        ate TGE+48m, quando libera os 75% restantes completos.
 *
 *      Custodia:
 *      - Alocacao e capturada dinamicamente: `totalAllocation() =
 *        balanceOf(this) + released`. Ou seja, o `owner` (Timelock) funda
 *        o contrato transferindo GOV via `gov.transfer(vesting, X)` apos
 *        o deploy, e o cronograma automaticamente reflete essa quantia.
 *        Transferencias adicionais posteriores aumentam a alocacao em
 *        tempo real (raramente desejavel; a DAO pode evitar simplesmente
 *        nao enviando mais). Esse e o mesmo padrao do OZ `VestingWallet`.
 *
 *      Revogacao:
 *      - O `owner` (Timelock via proposta) pode chamar {revoke} uma unica
 *        vez. Efeitos: (1) congela a fronteira de vesting em
 *        `totalAllocatedAtRevoke = vestedAmount(now)`; (2) devolve o
 *        saldo nao-vested imediatamente para `returnTo` (Treasury
 *        normalmente). O beneficiario continua podendo chamar {release}
 *        para sacar qualquer porcao vested-but-not-yet-released. Apos
 *        revoke, `vestedAmount` fica travado em `totalAllocatedAtRevoke`
 *        — o cronograma nao retoma se mais tokens forem enviados depois
 *        (imutabilidade contratual pos-revogacao).
 *
 *      Ownable2Step:
 *      - Deliberadamente escolhido (em vez de AccessControl) porque a
 *        autoridade sobre revogacao e inerentemente singular (DAO via
 *        Timelock) e o mecanismo 2-step protege contra transferencia
 *        de propriedade para endereco errado durante migracao.
 *
 *      Nao pausavel:
 *      - Mesma racional do Treasury: adicionar pause exigiria definir
 *        quem pode pausar, e qualquer poder unilateral de congelar o
 *        vesting do time e um vetor de captura. Se houver necessidade
 *        de "pausa", a DAO aprova uma proposta de {revoke} — que e
 *        semanticamente mais honesto.
 * @custom:security-contact security@web3community.example
 */
contract TeamVesting is Ownable2Step {
    using SafeERC20 for IERC20;

    // ------------------------------------------------------------------
    // Immutables
    // ------------------------------------------------------------------

    /// @notice Token sendo vested (em producao: GOV).
    IERC20 public immutable token;

    /// @notice Endereco que recebe os tokens liberados.
    address public immutable beneficiary;

    /// @notice Timestamp (unix seconds) em que o cronograma inicia.
    uint64 public immutable start;

    /// @notice Offset em segundos a partir de `start`. Antes do cliff,
    ///         releasable == 0.
    uint64 public immutable cliff;

    /// @notice Duracao TOTAL do cronograma em segundos (inclui o cliff).
    uint64 public immutable duration;

    // ------------------------------------------------------------------
    // Storage
    // ------------------------------------------------------------------

    /// @notice Total ja sacado pelo beneficiario via {release}.
    uint256 public released;

    /// @notice `true` apos uma chamada bem-sucedida a {revoke}.
    bool public revoked;

    /// @notice Timestamp do revoke (0 se nao revogado).
    uint64 public revokedAt;

    /// @notice Fronteira de vesting travada no momento do revoke. Apos
    ///         revoke, {vestedAmount} retorna sempre este valor.
    uint256 public totalAllocatedAtRevoke;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------

    /// @notice Emitido a cada liberacao para o beneficiario via {release}.
    /// @param beneficiary Endereco que recebeu.
    /// @param amount Quantidade transferida.
    event Released(address indexed beneficiary, uint256 amount);

    /// @notice Emitido na unica chamada a {revoke} bem-sucedida.
    /// @param returnedTo Destinatario da porcao nao-vested (Treasury).
    /// @param unvestedReturned Quantidade devolvida (pode ser zero se
    ///        revoke ocorre apos `start + duration`).
    /// @param frozenVested Valor congelado de {vestedAmount} pos-revoke.
    event Revoked(address indexed returnedTo, uint256 unvestedReturned, uint256 frozenVested);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    /// @notice Endereco zero nao e valido.
    error ZeroAddress();

    /// @notice Duracao zero nao faz sentido (divisao por zero).
    error ZeroDuration();

    /// @notice Cliff maior que duracao seria trava permanente.
    error CliffExceedsDuration();

    /// @notice Nada liberado (vested <= released ou cliff nao atingido).
    error NothingToRelease();

    /// @notice {revoke} e one-shot.
    error AlreadyRevoked();

    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------

    /**
     * @notice Configura cronograma imutavel. O contrato nao detem tokens
     *         ainda — o owner funda transferindo `token` para este
     *         endereco apos o deploy.
     * @dev Nao valida que `start` e futuro: a DAO pode deliberadamente
     *      iniciar o cronograma no passado (ex.: reconhecimento de
     *      servico anterior ao TGE). Se o beneficiario chama {release}
     *      logo apos o deploy e o passado for suficiente, o primeiro
     *      saque e imediato — comportamento intencional.
     * @param token_ ERC-20 sendo vested (GOV em producao).
     * @param beneficiary_ Endereco que recebe os releases.
     * @param start_ Timestamp de inicio do cronograma (unix seconds).
     * @param cliff_ Offset em segundos a partir de `start_`. Use 0 para
     *        desabilitar cliff.
     * @param duration_ Duracao total em segundos (inclui o cliff).
     * @param owner_ Endereco com poder de revogar (Timelock em producao).
     */
    constructor(
        address token_,
        address beneficiary_,
        uint64 start_,
        uint64 cliff_,
        uint64 duration_,
        address owner_
    ) Ownable(owner_) {
        if (token_ == address(0) || beneficiary_ == address(0)) {
            revert ZeroAddress();
        }
        if (duration_ == 0) {
            revert ZeroDuration();
        }
        if (cliff_ > duration_) {
            revert CliffExceedsDuration();
        }
        token = IERC20(token_);
        beneficiary = beneficiary_;
        start = start_;
        cliff = cliff_;
        duration = duration_;
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------

    /**
     * @notice Quantidade total ja vested em `timestamp`. Depois de
     *         revoke, retorna `totalAllocatedAtRevoke` (travado).
     * @param timestamp Unix seconds para consultar.
     */
    function vestedAmount(uint64 timestamp) public view returns (uint256) {
        return _vestedAmount(timestamp);
    }

    /**
     * @notice Quantidade pronta para saque agora (vested - released).
     */
    function releasable() public view returns (uint256) {
        uint256 vested = _vestedAmount(uint64(block.timestamp));
        if (vested <= released) {
            return 0;
        }
        return vested - released;
    }

    /**
     * @notice Alocacao total atualmente reconhecida pelo contrato.
     * @dev Antes de revoke: `balanceOf(this) + released`. Apos revoke:
     *      a fronteira congelada — o beneficiario so tem direito ao
     *      que estava vested no momento do revoke, independente de
     *      quanto saldo o contrato ainda carrega.
     */
    function totalAllocation() public view returns (uint256) {
        if (revoked) {
            return totalAllocatedAtRevoke;
        }
        return token.balanceOf(address(this)) + released;
    }

    // ------------------------------------------------------------------
    // Mutating — beneficiary
    // ------------------------------------------------------------------

    /**
     * @notice Saca tudo que esta releasable para o beneficiario.
     * @dev Pull-based: qualquer um pode chamar (ex.: o proprio
     *      beneficiario, um keeper), mas os tokens sempre vao para
     *      `beneficiary`. Reverte com {NothingToRelease} se nao ha
     *      nada para sacar — evita tx poluindo logs.
     *      CEI: checks -> effect (released += amount) -> interaction
     *      (safeTransfer). `safeTransfer` em token arbitrario e
     *      suficiente porque o owner e o Timelock (controle indireto
     *      do beneficiary); nao ha superficie de reentrancy relevante
     *      dado que `released` e incrementado antes da interacao.
     */
    function release() external {
        uint256 amount = releasable();
        if (amount == 0) {
            revert NothingToRelease();
        }
        released += amount;
        emit Released(beneficiary, amount);
        token.safeTransfer(beneficiary, amount);
    }

    // ------------------------------------------------------------------
    // Mutating — owner (DAO via Timelock)
    // ------------------------------------------------------------------

    /**
     * @notice Revoga o vesting. Congela a fronteira de vesting e devolve
     *         o saldo nao-vested para `returnTo` (Treasury).
     * @dev One-shot: chamadas subsequentes revertem com {AlreadyRevoked}.
     *      NAO transfere o vested-but-unreleased para o beneficiario
     *      automaticamente — o beneficiario deve chamar {release} para
     *      coletar. Essa separacao e intencional: mantem a UX "pull"
     *      do vested e evita transferencia surpresa para `beneficiary`
     *      (que pode ser um multi-sig offline no momento da proposta).
     *
     *      Cenarios por timing:
     *      - Antes do cliff: `vested = 0`, tudo volta para `returnTo`.
     *      - Entre cliff e duration: parte volta, parte fica travada
     *        pro beneficiario.
     *      - Depois de duration: nada volta (tudo ja era vested); o
     *        contrato so trava a fronteira em `totalAllocation`.
     *
     *      `released` NAO e alterado — continua contabilizando saques
     *      passados. O invariante `released <= totalAllocatedAtRevoke`
     *      e garantido porque em qualquer saque passado `released <=
     *      vestedAmount(t) <= vestedAmount(now)`.
     * @param returnTo Destinatario da porcao nao-vested. Tipicamente
     *        o Treasury da DAO.
     */
    function revoke(address returnTo) external onlyOwner {
        if (revoked) {
            revert AlreadyRevoked();
        }
        if (returnTo == address(0)) {
            revert ZeroAddress();
        }

        uint256 vestedNow = _vestedAmount(uint64(block.timestamp));
        uint256 currentBalance = token.balanceOf(address(this));
        uint256 total = currentBalance + released;
        uint256 unvested = total > vestedNow ? total - vestedNow : 0;

        revoked = true;
        revokedAt = uint64(block.timestamp);
        totalAllocatedAtRevoke = vestedNow;

        emit Revoked(returnTo, unvested, vestedNow);
        if (unvested > 0) {
            token.safeTransfer(returnTo, unvested);
        }
    }

    // ------------------------------------------------------------------
    // Internal
    // ------------------------------------------------------------------

    /**
     * @dev Formula linear padrao OZ:
     *        vested(t) = 0                                  se t < start + cliff
     *        vested(t) = total                              se t >= start + duration
     *        vested(t) = total * (t - start) / duration     caso contrario
     *      Apos revoke, ignora a formula e retorna
     *      `totalAllocatedAtRevoke` (fronteira travada).
     */
    function _vestedAmount(uint64 timestamp) private view returns (uint256) {
        if (revoked) {
            return totalAllocatedAtRevoke;
        }
        uint64 cliffEnd = start + cliff;
        if (timestamp < cliffEnd) {
            return 0;
        }
        uint256 total = token.balanceOf(address(this)) + released;
        if (timestamp >= start + duration) {
            return total;
        }
        return (total * (timestamp - start)) / duration;
    }
}

